    AutoMLCandidate.add_member(:final_auto_ml_job_objective_metric, Smithy::Schema::Shapes::ShapeRef.new(shape: FinalAutoMLJobObjectiveMetric, location_name: 'FinalAutoMLJobObjectiveMetric'))
    AutoMLCandidate.add_member(:objective_status, Smithy::Schema::Shapes::ShapeRef.new(shape: ObjectiveStatus, location_name: 'ObjectiveStatus', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The objective's status.</p>", "smithy.api#required" => {}}))
