    CheckpointConfig.add_member(:local_path, Smithy::Schema::Shapes::ShapeRef.new(shape: DirectoryPath, location_name: 'LocalPath', traits: {"smithy.api#documentation" => "<p>(Optional) The local directory where checkpoints are written. The default directory is <code>/opt/ml/checkpoints/</code>. </p>"}))
