    ClarifyCheckStepMetadata.add_member(:baseline_used_for_drift_check_constraints, Smithy::Schema::Shapes::ShapeRef.new(shape: String1024, location_name: 'BaselineUsedForDriftCheckConstraints', traits: {"smithy.api#documentation" => "<p>The Amazon S3 URI of baseline constraints file to be used for the drift check.</p>"}))
    ClarifyCheckStepMetadata.add_member(:calculated_baseline_constraints, Smithy::Schema::Shapes::ShapeRef.new(shape: String1024, location_name: 'CalculatedBaselineConstraints', traits: {"smithy.api#documentation" => "<p>The Amazon S3 URI of the newly calculated baseline constraints file.</p>"}))
    ClarifyCheckStepMetadata.add_member(:model_package_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String256, location_name: 'ModelPackageGroupName', traits: {"smithy.api#documentation" => "<p>The model package group name.</p>"}))
    ClarifyCheckStepMetadata.add_member(:violation_report, Smithy::Schema::Shapes::ShapeRef.new(shape: String1024, location_name: 'ViolationReport', traits: {"smithy.api#documentation" => "<p>The Amazon S3 URI of the violation report if violations are detected.</p>"}))
    ClarifyCheckStepMetadata.add_member(:check_job_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String256, location_name: 'CheckJobArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the check processing job that was run by this step's execution.</p>"}))
    ClarifyCheckStepMetadata.add_member(:skip_check, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'SkipCheck', traits: {"smithy.api#documentation" => "<p>This flag indicates if the drift check against the previous baseline will be skipped or not. If it is set to <code>False</code>, the previous baseline of the configured check type must be available.</p>"}))
    ClarifyCheckStepMetadata.add_member(:register_new_baseline, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'RegisterNewBaseline', traits: {"smithy.api#documentation" => "<p>This flag indicates if a newly calculated baseline can be accessed through step properties <code>BaselineUsedForDriftCheckConstraints</code> and <code>BaselineUsedForDriftCheckStatistics</code>. If it is set to <code>False</code>, the previous baseline of the configured check type must also be available. These can be accessed through the <code>BaselineUsedForDriftCheckConstraints</code> property. </p>"}))
    ClarifyCheckStepMetadata.type = Types::ClarifyCheckStepMetadata
    ClarifyExplainerConfig.add_member(:enable_explanations, Smithy::Schema::Shapes::ShapeRef.new(shape: ClarifyEnableExplanations, location_name: 'EnableExplanations', traits: {"smithy.api#documentation" => "<p>A JMESPath boolean expression used to filter which records to explain. Explanations are activated by default. See <a href=\"https://docs.aws.amazon.com/sagemaker/latest/dg/clarify-online-explainability-create-endpoint.html#clarify-online-explainability-create-endpoint-enable\"> <code>EnableExplanations</code> </a>for additional information.</p>"}))
    ClarifyExplainerConfig.add_member(:inference_config, Smithy::Schema::Shapes::ShapeRef.new(shape: ClarifyInferenceConfig, location_name: 'InferenceConfig', traits: {"smithy.api#documentation" => "<p>The inference configuration parameter for the model container.</p>"}))
    ClarifyExplainerConfig.add_member(:shap_config, Smithy::Schema::Shapes::ShapeRef.new(shape: ClarifyShapConfig, location_name: 'ShapConfig', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The configuration for SHAP analysis.</p>", "smithy.api#required" => {}}))
    ClarifyExplainerConfig.type = Types::ClarifyExplainerConfig
    ClarifyFeatureHeaders.member = Smithy::Schema::Shapes::ShapeRef.new(shape: ClarifyHeader)
    ClarifyFeatureType.add_member(:numerical, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'NUMERICAL', traits: {"smithy.api#enumValue" => "numerical"}))
    ClarifyFeatureType.add_member(:categorical, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'CATEGORICAL', traits: {"smithy.api#enumValue" => "categorical"}))
    ClarifyFeatureType.add_member(:text, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'TEXT', traits: {"smithy.api#enumValue" => "text"}))
    ClarifyFeatureTypes.member = Smithy::Schema::Shapes::ShapeRef.new(shape: ClarifyFeatureType)
    ClarifyInferenceConfig.add_member(:features_attribute, Smithy::Schema::Shapes::ShapeRef.new(shape: ClarifyFeaturesAttribute, location_name: 'FeaturesAttribute', traits: {"smithy.api#documentation" => "<p>Provides the JMESPath expression to extract the features from a model container input in JSON Lines format. For example, if <code>FeaturesAttribute</code> is the JMESPath expression <code>'myfeatures'</code>, it extracts a list of features <code>[1,2,3]</code> from request data <code>'{\"myfeatures\":[1,2,3]}'</code>.</p>"}))
    ClarifyInferenceConfig.add_member(:content_template, Smithy::Schema::Shapes::ShapeRef.new(shape: ClarifyContentTemplate, location_name: 'ContentTemplate', traits: {"smithy.api#documentation" => "<p>A template string used to format a JSON record into an acceptable model container input. For example, a <code>ContentTemplate</code> string <code>'{\"myfeatures\":$features}'</code> will format a list of features <code>[1,2,3]</code> into the record string <code>'{\"myfeatures\":[1,2,3]}'</code>. Required only when the model container input is in JSON Lines format.</p>"}))
    ClarifyInferenceConfig.add_member(:max_record_count, Smithy::Schema::Shapes::ShapeRef.new(shape: ClarifyMaxRecordCount, location_name: 'MaxRecordCount', traits: {"smithy.api#documentation" => "<p>The maximum number of records in a request that the model container can process when querying the model container for the predictions of a <a href=\"https://docs.aws.amazon.com/sagemaker/latest/dg/clarify-online-explainability-create-endpoint.html#clarify-online-explainability-create-endpoint-synthetic\">synthetic dataset</a>. A record is a unit of input data that inference can be made on, for example, a single line in CSV data. If <code>MaxRecordCount</code> is <code>1</code>, the model container expects one record per request. A value of 2 or greater means that the model expects batch requests, which can reduce overhead and speed up the inferencing process. If this parameter is not provided, the explainer will tune the record count per request according to the model container's capacity at runtime.</p>"}))
    ClarifyInferenceConfig.add_member(:max_payload_in_mb, Smithy::Schema::Shapes::ShapeRef.new(shape: ClarifyMaxPayloadInMB, location_name: 'MaxPayloadInMB', traits: {"smithy.api#documentation" => "<p>The maximum payload size (MB) allowed of a request from the explainer to the model container. Defaults to <code>6</code> MB.</p>"}))
    ClarifyInferenceConfig.add_member(:probability_index, Smithy::Schema::Shapes::ShapeRef.new(shape: ClarifyProbabilityIndex, location_name: 'ProbabilityIndex', traits: {"smithy.api#documentation" => "<p>A zero-based index used to extract a probability value (score) or list from model container output in CSV format. If this value is not provided, the entire model container output will be treated as a probability value (score) or list.</p> <p> <b>Example for a single class model:</b> If the model container output consists of a string-formatted prediction label followed by its probability: <code>'1,0.6'</code>, set <code>ProbabilityIndex</code> to <code>1</code> to select the probability value <code>0.6</code>.</p> <p> <b>Example for a multiclass model:</b> If the model container output consists of a string-formatted prediction label followed by its probability: <code>'\"[\\'cat\\',\\'dog\\',\\'fish\\']\",\"[0.1,0.6,0.3]\"'</code>, set <code>ProbabilityIndex</code> to <code>1</code> to select the probability values <code>[0.1,0.6,0.3]</code>.</p>"}))
    ClarifyInferenceConfig.add_member(:label_index, Smithy::Schema::Shapes::ShapeRef.new(shape: ClarifyLabelIndex, location_name: 'LabelIndex', traits: {"smithy.api#documentation" => "<p>A zero-based index used to extract a label header or list of label headers from model container output in CSV format.</p> <p> <b>Example for a multiclass model:</b> If the model container output consists of label headers followed by probabilities: <code>'\"[\\'cat\\',\\'dog\\',\\'fish\\']\",\"[0.1,0.6,0.3]\"'</code>, set <code>LabelIndex</code> to <code>0</code> to select the label headers <code>['cat','dog','fish']</code>.</p>"}))
    ClarifyInferenceConfig.add_member(:probability_attribute, Smithy::Schema::Shapes::ShapeRef.new(shape: ClarifyProbabilityAttribute, location_name: 'ProbabilityAttribute', traits: {"smithy.api#documentation" => "<p>A JMESPath expression used to extract the probability (or score) from the model container output if the model container is in JSON Lines format.</p> <p> <b>Example</b>: If the model container output of a single request is <code>'{\"predicted_label\":1,\"probability\":0.6}'</code>, then set <code>ProbabilityAttribute</code> to <code>'probability'</code>.</p>"}))
    ClarifyInferenceConfig.add_member(:label_attribute, Smithy::Schema::Shapes::ShapeRef.new(shape: ClarifyLabelAttribute, location_name: 'LabelAttribute', traits: {"smithy.api#documentation" => "<p>A JMESPath expression used to locate the list of label headers in the model container output.</p> <p> <b>Example</b>: If the model container output of a batch request is <code>'{\"labels\":[\"cat\",\"dog\",\"fish\"],\"probability\":[0.6,0.3,0.1]}'</code>, then set <code>LabelAttribute</code> to <code>'labels'</code> to extract the list of label headers <code>[\"cat\",\"dog\",\"fish\"]</code> </p>"}))
    ClarifyInferenceConfig.add_member(:label_headers, Smithy::Schema::Shapes::ShapeRef.new(shape: ClarifyLabelHeaders, location_name: 'LabelHeaders', traits: {"smithy.api#documentation" => "<p>For multiclass classification problems, the label headers are the names of the classes. Otherwise, the label header is the name of the predicted label. These are used to help readability for the output of the <code>InvokeEndpoint</code> API. See the <a href=\"https://docs.aws.amazon.com/sagemaker/latest/dg/clarify-online-explainability-invoke-endpoint.html#clarify-online-explainability-response\">response</a> section under <b>Invoke the endpoint</b> in the Developer Guide for more information. If there are no label headers in the model container output, provide them manually using this parameter.</p>"}))
    ClarifyInferenceConfig.add_member(:feature_headers, Smithy::Schema::Shapes::ShapeRef.new(shape: ClarifyFeatureHeaders, location_name: 'FeatureHeaders', traits: {"smithy.api#documentation" => "<p>The names of the features. If provided, these are included in the endpoint response payload to help readability of the <code>InvokeEndpoint</code> output. See the <a href=\"https://docs.aws.amazon.com/sagemaker/latest/dg/clarify-online-explainability-invoke-endpoint.html#clarify-online-explainability-response\">Response</a> section under <b>Invoke the endpoint</b> in the Developer Guide for more information.</p>"}))
    ClarifyInferenceConfig.add_member(:feature_types, Smithy::Schema::Shapes::ShapeRef.new(shape: ClarifyFeatureTypes, location_name: 'FeatureTypes', traits: {"smithy.api#documentation" => "<p>A list of data types of the features (optional). Applicable only to NLP explainability. If provided, <code>FeatureTypes</code> must have at least one <code>'text'</code> string (for example, <code>['text']</code>). If <code>FeatureTypes</code> is not provided, the explainer infers the feature types based on the baseline data. The feature types are included in the endpoint response payload. For additional information see the <a href=\"https://docs.aws.amazon.com/sagemaker/latest/dg/clarify-online-explainability-invoke-endpoint.html#clarify-online-explainability-response\">response</a> section under <b>Invoke the endpoint</b> in the Developer Guide for more information.</p>"}))
    ClarifyInferenceConfig.type = Types::ClarifyInferenceConfig
    ClarifyLabelHeaders.member = Smithy::Schema::Shapes::ShapeRef.new(shape: ClarifyHeader)
    ClarifyShapBaselineConfig.add_member(:mime_type, Smithy::Schema::Shapes::ShapeRef.new(shape: ClarifyMimeType, location_name: 'MimeType', traits: {"smithy.api#documentation" => "<p>The MIME type of the baseline data. Choose from <code>'text/csv'</code> or <code>'application/jsonlines'</code>. Defaults to <code>'text/csv'</code>.</p>"}))
    ClarifyShapBaselineConfig.add_member(:shap_baseline, Smithy::Schema::Shapes::ShapeRef.new(shape: ClarifyShapBaseline, location_name: 'ShapBaseline', traits: {"smithy.api#documentation" => "<p>The inline SHAP baseline data in string format. <code>ShapBaseline</code> can have one or multiple records to be used as the baseline dataset. The format of the SHAP baseline file should be the same format as the training dataset. For example, if the training dataset is in CSV format and each record contains four features, and all features are numerical, then the format of the baseline data should also share these characteristics. For natural language processing (NLP) of text columns, the baseline value should be the value used to replace the unit of text specified by the <code>Granularity</code> of the <code>TextConfig</code> parameter. The size limit for <code>ShapBasline</code> is 4 KB. Use the <code>ShapBaselineUri</code> parameter if you want to provide more than 4 KB of baseline data.</p>"}))
    ClarifyShapBaselineConfig.add_member(:shap_baseline_uri, Smithy::Schema::Shapes::ShapeRef.new(shape: Url, location_name: 'ShapBaselineUri', traits: {"smithy.api#documentation" => "<p>The uniform resource identifier (URI) of the S3 bucket where the SHAP baseline file is stored. The format of the SHAP baseline file should be the same format as the format of the training dataset. For example, if the training dataset is in CSV format, and each record in the training dataset has four features, and all features are numerical, then the baseline file should also have this same format. Each record should contain only the features. If you are using a virtual private cloud (VPC), the <code>ShapBaselineUri</code> should be accessible to the VPC. For more information about setting up endpoints with Amazon Virtual Private Cloud, see <a href=\"https://docs.aws.amazon.com/sagemaker/latest/dg/infrastructure-give-access.html\">Give SageMaker access to Resources in your Amazon Virtual Private Cloud</a>.</p>"}))
    ClarifyShapBaselineConfig.type = Types::ClarifyShapBaselineConfig
    ClarifyShapConfig.add_member(:shap_baseline_config, Smithy::Schema::Shapes::ShapeRef.new(shape: ClarifyShapBaselineConfig, location_name: 'ShapBaselineConfig', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The configuration for the SHAP baseline of the Kernal SHAP algorithm.</p>", "smithy.api#required" => {}}))
    ClarifyShapConfig.add_member(:number_of_samples, Smithy::Schema::Shapes::ShapeRef.new(shape: ClarifyShapNumberOfSamples, location_name: 'NumberOfSamples', traits: {"smithy.api#documentation" => "<p>The number of samples to be used for analysis by the Kernal SHAP algorithm. </p> <note> <p>The number of samples determines the size of the synthetic dataset, which has an impact on latency of explainability requests. For more information, see the <b>Synthetic data</b> of <a href=\"https://docs.aws.amazon.com/sagemaker/latest/dg/clarify-online-explainability-create-endpoint.html\">Configure and create an endpoint</a>.</p> </note>"}))
    ClarifyShapConfig.add_member(:use_logit, Smithy::Schema::Shapes::ShapeRef.new(shape: ClarifyShapUseLogit, location_name: 'UseLogit', traits: {"smithy.api#documentation" => "<p>A Boolean toggle to indicate if you want to use the logit function (true) or log-odds units (false) for model predictions. Defaults to false.</p>"}))
    ClarifyShapConfig.add_member(:seed, Smithy::Schema::Shapes::ShapeRef.new(shape: ClarifyShapSeed, location_name: 'Seed', traits: {"smithy.api#documentation" => "<p>The starting value used to initialize the random number generator in the explainer. Provide a value for this parameter to obtain a deterministic SHAP result.</p>"}))
    ClarifyShapConfig.add_member(:text_config, Smithy::Schema::Shapes::ShapeRef.new(shape: ClarifyTextConfig, location_name: 'TextConfig', traits: {"smithy.api#documentation" => "<p>A parameter that indicates if text features are treated as text and explanations are provided for individual units of text. Required for natural language processing (NLP) explainability only.</p>"}))
    ClarifyShapConfig.type = Types::ClarifyShapConfig
    ClarifyTextConfig.add_member(:language, Smithy::Schema::Shapes::ShapeRef.new(shape: ClarifyTextLanguage, location_name: 'Language', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>Specifies the language of the text features in <a href=\" https://en.wikipedia.org/wiki/List_of_ISO_639-1_codes\">ISO 639-1</a> or <a href=\"https://en.wikipedia.org/wiki/ISO_639-3\">ISO 639-3</a> code of a supported language. </p> <note> <p>For a mix of multiple languages, use code <code>'xx'</code>.</p> </note>", "smithy.api#required" => {}}))
    ClarifyTextConfig.add_member(:granularity, Smithy::Schema::Shapes::ShapeRef.new(shape: ClarifyTextGranularity, location_name: 'Granularity', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The unit of granularity for the analysis of text features. For example, if the unit is <code>'token'</code>, then each token (like a word in English) of the text is treated as a feature. SHAP values are computed for each unit/feature.</p>", "smithy.api#required" => {}}))
    ClarifyTextConfig.type = Types::ClarifyTextConfig
