    ContinuousParameterRangeSpecification.add_member(:max_value, Smithy::Schema::Shapes::ShapeRef.new(shape: ParameterValue, location_name: 'MaxValue', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The maximum floating-point value allowed.</p>", "smithy.api#required" => {}}))
