    CreateAutoMLJobRequest.add_member(:auto_ml_job_name, Smithy::Schema::Shapes::ShapeRef.new(shape: AutoMLJobName, location_name: 'AutoMLJobName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>Identifies an Autopilot job. The name must be unique to your account and is case insensitive.</p>", "smithy.api#required" => {}}))
    CreateAutoMLJobRequest.add_member(:input_data_config, Smithy::Schema::Shapes::ShapeRef.new(shape: AutoMLInputDataConfig, location_name: 'InputDataConfig', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>An array of channel objects that describes the input data and its location. Each channel is a named input source. Similar to <code>InputDataConfig</code> supported by <a href=\"https://docs.aws.amazon.com/sagemaker/latest/APIReference/API_HyperParameterTrainingJobDefinition.html\">HyperParameterTrainingJobDefinition</a>. Format(s) supported: CSV, Parquet. A minimum of 500 rows is required for the training dataset. There is not a minimum number of rows required for the validation dataset.</p>", "smithy.api#required" => {}}))
    CreateAutoMLJobRequest.add_member(:output_data_config, Smithy::Schema::Shapes::ShapeRef.new(shape: AutoMLOutputDataConfig, location_name: 'OutputDataConfig', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>Provides information about encryption and the Amazon S3 output path needed to store artifacts from an AutoML job. Format(s) supported: CSV.</p>", "smithy.api#required" => {}}))
    CreateAutoMLJobRequest.add_member(:problem_type, Smithy::Schema::Shapes::ShapeRef.new(shape: ProblemType, location_name: 'ProblemType', traits: {"smithy.api#documentation" => "<p>Defines the type of supervised learning problem available for the candidates. For more information, see <a href=\"https://docs.aws.amazon.com/sagemaker/latest/dg/autopilot-datasets-problem-types.html#autopilot-problem-types\"> SageMaker Autopilot problem types</a>.</p>"}))
    CreateAutoMLJobRequest.add_member(:auto_ml_job_objective, Smithy::Schema::Shapes::ShapeRef.new(shape: AutoMLJobObjective, location_name: 'AutoMLJobObjective', traits: {"smithy.api#documentation" => "<p>Specifies a metric to minimize or maximize as the objective of a job. If not specified, the default objective metric depends on the problem type. See <a href=\"https://docs.aws.amazon.com/sagemaker/latest/APIReference/API_AutoMLJobObjective.html\">AutoMLJobObjective</a> for the default values.</p>"}))
    CreateAutoMLJobRequest.add_member(:auto_ml_job_config, Smithy::Schema::Shapes::ShapeRef.new(shape: AutoMLJobConfig, location_name: 'AutoMLJobConfig', traits: {"smithy.api#documentation" => "<p>A collection of settings used to configure an AutoML job.</p>"}))
    CreateAutoMLJobRequest.add_member(:role_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: RoleArn, location_name: 'RoleArn', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The ARN of the role that is used to access the data.</p>", "smithy.api#required" => {}}))
    CreateAutoMLJobRequest.add_member(:generate_candidate_definitions_only, Smithy::Schema::Shapes::ShapeRef.new(shape: GenerateCandidateDefinitionsOnly, location_name: 'GenerateCandidateDefinitionsOnly', traits: {"smithy.api#documentation" => "<p>Generates possible candidates without training the models. A candidate is a combination of data preprocessors, algorithms, and algorithm parameter settings.</p>"}))
    CreateAutoMLJobRequest.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagList, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>An array of key-value pairs. You can use tags to categorize your Amazon Web Services resources in different ways, for example, by purpose, owner, or environment. For more information, see <a href=\"https://docs.aws.amazon.com/general/latest/gr/aws_tagging.html\">Tagging Amazon Web ServicesResources</a>. Tag keys must be unique per resource.</p>"}))
    CreateAutoMLJobRequest.add_member(:model_deploy_config, Smithy::Schema::Shapes::ShapeRef.new(shape: ModelDeployConfig, location_name: 'ModelDeployConfig', traits: {"smithy.api#documentation" => "<p>Specifies how to generate the endpoint name for an automatic one-click Autopilot model deployment.</p>"}))
    CreateAutoMLJobRequest.type = Types::CreateAutoMLJobRequest
