    CreateComputeQuotaRequest.add_member(:name, Smithy::Schema::Shapes::ShapeRef.new(shape: EntityName, location_name: 'Name', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>Name to the compute allocation definition.</p>", "smithy.api#required" => {}}))
