    CreateComputeQuotaRequest.add_member(:compute_quota_config, Smithy::Schema::Shapes::ShapeRef.new(shape: ComputeQuotaConfig, location_name: 'ComputeQuotaConfig', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>Configuration of the compute allocation definition. This includes the resource sharing option, and the setting to preempt low priority tasks.</p>", "smithy.api#required" => {}}))
    CreateComputeQuotaRequest.add_member(:compute_quota_target, Smithy::Schema::Shapes::ShapeRef.new(shape: ComputeQuotaTarget, location_name: 'ComputeQuotaTarget', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The target entity to allocate compute resources to.</p>", "smithy.api#required" => {}}))
    CreateComputeQuotaRequest.add_member(:activation_state, Smithy::Schema::Shapes::ShapeRef.new(shape: ActivationState, location_name: 'ActivationState', traits: {"smithy.api#documentation" => "<p>The state of the compute allocation being described. Use to enable or disable compute allocation.</p> <p>Default is <code>Enabled</code>.</p>"}))
