    CreateExperimentRequest.add_member(:display_name, Smithy::Schema::Shapes::ShapeRef.new(shape: ExperimentEntityName, location_name: 'DisplayName', traits: {"smithy.api#documentation" => "<p>The name of the experiment as displayed. The name doesn't need to be unique. If you don't specify <code>DisplayName</code>, the value in <code>ExperimentName</code> is displayed.</p>"}))
