    CreateHubContentPresignedUrlsRequest.add_member(:hub_content_name, Smithy::Schema::Shapes::ShapeRef.new(shape: HubContentName, location_name: 'HubContentName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name of the hub content for which to generate presigned URLs. This identifies the specific model or content within the hub.</p>", "smithy.api#required" => {}}))
