    CreateHubContentPresignedUrlsRequest.add_member(:access_config, Smithy::Schema::Shapes::ShapeRef.new(shape: PresignedUrlAccessConfig, location_name: 'AccessConfig', traits: {"smithy.api#documentation" => "<p>Configuration settings for accessing the hub content, including end-user license agreement acceptance for gated models and expected S3 URL validation.</p>"}))
    CreateHubContentPresignedUrlsRequest.add_member(:max_results, Smithy::Schema::Shapes::ShapeRef.new(shape: MaxResults, location_name: 'MaxResults', traits: {"smithy.api#documentation" => "<p>The maximum number of presigned URLs to return in the response. Default value is 100. Large models may contain hundreds of files, requiring pagination to retrieve all URLs.</p>"}))
