    CreateImageVersionRequest.add_member(:base_image, Smithy::Schema::Shapes::ShapeRef.new(shape: ImageBaseImage, location_name: 'BaseImage', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The registry path of the container image to use as the starting point for this version. The path is an Amazon ECR URI in the following format:</p> <p> <code>&lt;acct-id&gt;.dkr.ecr.&lt;region&gt;.amazonaws.com/&lt;repo-name[:tag] or [@digest]&gt;</code> </p>", "smithy.api#required" => {}}))
    CreateImageVersionRequest.add_member(:client_token, Smithy::Schema::Shapes::ShapeRef.new(shape: ClientToken, location_name: 'ClientToken', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>A unique ID. If not specified, the Amazon Web Services CLI and Amazon Web Services SDKs, such as the SDK for Python (Boto3), add a unique value to the call.</p>", "smithy.api#idempotencyToken" => {}, "smithy.api#required" => {}}))
    CreateImageVersionRequest.add_member(:image_name, Smithy::Schema::Shapes::ShapeRef.new(shape: ImageName, location_name: 'ImageName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The <code>ImageName</code> of the <code>Image</code> to create a version of.</p>", "smithy.api#required" => {}}))
    CreateImageVersionRequest.add_member(:aliases, Smithy::Schema::Shapes::ShapeRef.new(shape: SageMakerImageVersionAliases, location_name: 'Aliases', traits: {"smithy.api#documentation" => "<p>A list of aliases created with the image version.</p>"}))
    CreateImageVersionRequest.add_member(:vendor_guidance, Smithy::Schema::Shapes::ShapeRef.new(shape: VendorGuidance, location_name: 'VendorGuidance', traits: {"smithy.api#documentation" => "<p>The stability of the image version, specified by the maintainer.</p> <ul> <li> <p> <code>NOT_PROVIDED</code>: The maintainers did not provide a status for image version stability.</p> </li> <li> <p> <code>STABLE</code>: The image version is stable.</p> </li> <li> <p> <code>TO_BE_ARCHIVED</code>: The image version is set to be archived. Custom image versions that are set to be archived are automatically archived after three months.</p> </li> <li> <p> <code>ARCHIVED</code>: The image version is archived. Archived image versions are not searchable and are no longer actively supported. </p> </li> </ul>"}))
    CreateImageVersionRequest.add_member(:job_type, Smithy::Schema::Shapes::ShapeRef.new(shape: JobType, location_name: 'JobType', traits: {"smithy.api#documentation" => "<p>Indicates SageMaker AI job type compatibility.</p> <ul> <li> <p> <code>TRAINING</code>: The image version is compatible with SageMaker AI training jobs.</p> </li> <li> <p> <code>INFERENCE</code>: The image version is compatible with SageMaker AI inference jobs.</p> </li> <li> <p> <code>NOTEBOOK_KERNEL</code>: The image version is compatible with SageMaker AI notebook kernels.</p> </li> </ul>"}))
    CreateImageVersionRequest.add_member(:ml_framework, Smithy::Schema::Shapes::ShapeRef.new(shape: MLFramework, location_name: 'MLFramework', traits: {"smithy.api#documentation" => "<p>The machine learning framework vended in the image version.</p>"}))
    CreateImageVersionRequest.add_member(:programming_lang, Smithy::Schema::Shapes::ShapeRef.new(shape: ProgrammingLang, location_name: 'ProgrammingLang', traits: {"smithy.api#documentation" => "<p>The supported programming language and its version.</p>"}))
    CreateImageVersionRequest.add_member(:processor, Smithy::Schema::Shapes::ShapeRef.new(shape: Processor, location_name: 'Processor', traits: {"smithy.api#documentation" => "<p>Indicates CPU or GPU compatibility.</p> <ul> <li> <p> <code>CPU</code>: The image version is compatible with CPU.</p> </li> <li> <p> <code>GPU</code>: The image version is compatible with GPU.</p> </li> </ul>"}))
    CreateImageVersionRequest.add_member(:horovod, Smithy::Schema::Shapes::ShapeRef.new(shape: Horovod, location_name: 'Horovod', traits: {"smithy.api#documentation" => "<p>Indicates Horovod compatibility.</p>"}))
    CreateImageVersionRequest.add_member(:release_notes, Smithy::Schema::Shapes::ShapeRef.new(shape: ReleaseNotes, location_name: 'ReleaseNotes', traits: {"smithy.api#documentation" => "<p>The maintainer description of the image version.</p>"}))
