    CreateInferenceComponentInput.add_member(:endpoint_name, Smithy::Schema::Shapes::ShapeRef.new(shape: EndpointName, location_name: 'EndpointName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name of an existing endpoint where you host the inference component.</p>", "smithy.api#required" => {}}))
    CreateInferenceComponentInput.add_member(:variant_name, Smithy::Schema::Shapes::ShapeRef.new(shape: VariantName, location_name: 'VariantName', traits: {"smithy.api#documentation" => "<p>The name of an existing production variant where you host the inference component.</p>"}))
    CreateInferenceComponentInput.add_member(:specification, Smithy::Schema::Shapes::ShapeRef.new(shape: InferenceComponentSpecification, location_name: 'Specification', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>Details about the resources to deploy with this inference component, including the model, container, and compute resources.</p>", "smithy.api#required" => {}}))
    CreateInferenceComponentInput.add_member(:runtime_config, Smithy::Schema::Shapes::ShapeRef.new(shape: InferenceComponentRuntimeConfig, location_name: 'RuntimeConfig', traits: {"smithy.api#documentation" => "<p>Runtime settings for a model that is deployed with an inference component.</p>"}))
    CreateInferenceComponentInput.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagList, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>A list of key-value pairs associated with the model. For more information, see <a href=\"https://docs.aws.amazon.com/general/latest/gr/aws_tagging.html\">Tagging Amazon Web Services resources</a> in the <i>Amazon Web Services General Reference</i>.</p>"}))
