    CreateMlflowTrackingServerRequest.add_member(:tracking_server_name, Smithy::Schema::Shapes::ShapeRef.new(shape: TrackingServerName, location_name: 'TrackingServerName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>A unique string identifying the tracking server name. This string is part of the tracking server ARN.</p>", "smithy.api#required" => {}}))
