    CreateNotebookInstanceLifecycleConfigInput.add_member(:on_create, Smithy::Schema::Shapes::ShapeRef.new(shape: NotebookInstanceLifecycleConfigList, location_name: 'OnCreate', traits: {"smithy.api#documentation" => "<p>A shell script that runs only once, when you create a notebook instance. The shell script must be a base64-encoded string.</p>"}))
    CreateNotebookInstanceLifecycleConfigInput.add_member(:on_start, Smithy::Schema::Shapes::ShapeRef.new(shape: NotebookInstanceLifecycleConfigList, location_name: 'OnStart', traits: {"smithy.api#documentation" => "<p>A shell script that runs every time you start a notebook instance, including when you create the notebook instance. The shell script must be a base64-encoded string.</p>"}))
