    CreateStudioLifecycleConfigRequest.add_member(:studio_lifecycle_config_name, Smithy::Schema::Shapes::ShapeRef.new(shape: StudioLifecycleConfigName, location_name: 'StudioLifecycleConfigName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name of the Amazon SageMaker AI Studio Lifecycle Configuration to create.</p>", "smithy.api#required" => {}}))
    CreateStudioLifecycleConfigRequest.add_member(:studio_lifecycle_config_content, Smithy::Schema::Shapes::ShapeRef.new(shape: StudioLifecycleConfigContent, location_name: 'StudioLifecycleConfigContent', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The content of your Amazon SageMaker AI Studio Lifecycle Configuration script. This content must be base64 encoded.</p>", "smithy.api#required" => {}}))
    CreateStudioLifecycleConfigRequest.add_member(:studio_lifecycle_config_app_type, Smithy::Schema::Shapes::ShapeRef.new(shape: StudioLifecycleConfigAppType, location_name: 'StudioLifecycleConfigAppType', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The App type that the Lifecycle Configuration is attached to.</p>", "smithy.api#required" => {}}))
