    CreateTrainingPlanRequest.add_member(:training_plan_offering_id, Smithy::Schema::Shapes::ShapeRef.new(shape: TrainingPlanOfferingId, location_name: 'TrainingPlanOfferingId', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The unique identifier of the training plan offering to use for creating this plan.</p>", "smithy.api#required" => {}}))
    CreateTrainingPlanRequest.add_member(:spare_instance_count_per_ultra_server, Smithy::Schema::Shapes::ShapeRef.new(shape: SpareInstanceCountPerUltraServer, location_name: 'SpareInstanceCountPerUltraServer', traits: {"smithy.api#documentation" => "<p>Number of spare instances to reserve per UltraServer for enhanced resiliency. Default is 1.</p>"}))
    CreateTrainingPlanRequest.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagList, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>An array of key-value pairs to apply to this training plan.</p>"}))
