    CreateTrialComponentRequest.add_member(:trial_component_name, Smithy::Schema::Shapes::ShapeRef.new(shape: ExperimentEntityName, location_name: 'TrialComponentName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name of the component. The name must be unique in your Amazon Web Services account and is not case-sensitive.</p>", "smithy.api#required" => {}}))
    CreateTrialComponentRequest.add_member(:display_name, Smithy::Schema::Shapes::ShapeRef.new(shape: ExperimentEntityName, location_name: 'DisplayName', traits: {"smithy.api#documentation" => "<p>The name of the component as displayed. The name doesn't need to be unique. If <code>DisplayName</code> isn't specified, <code>TrialComponentName</code> is displayed.</p>"}))
    CreateTrialComponentRequest.add_member(:status, Smithy::Schema::Shapes::ShapeRef.new(shape: TrialComponentStatus, location_name: 'Status', traits: {"smithy.api#documentation" => "<p>The status of the component. States include:</p> <ul> <li> <p>InProgress</p> </li> <li> <p>Completed</p> </li> <li> <p>Failed</p> </li> </ul>"}))
    CreateTrialComponentRequest.add_member(:start_time, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'StartTime', traits: {"smithy.api#documentation" => "<p>When the component started.</p>"}))
