    CreateTrialComponentRequest.add_member(:input_artifacts, Smithy::Schema::Shapes::ShapeRef.new(shape: TrialComponentArtifacts, location_name: 'InputArtifacts', traits: {"smithy.api#documentation" => "<p>The input artifacts for the component. Examples of input artifacts are datasets, algorithms, hyperparameters, source code, and instance types.</p>"}))
    CreateTrialComponentRequest.add_member(:output_artifacts, Smithy::Schema::Shapes::ShapeRef.new(shape: TrialComponentArtifacts, location_name: 'OutputArtifacts', traits: {"smithy.api#documentation" => "<p>The output artifacts for the component. Examples of output artifacts are metrics, snapshots, logs, and images.</p>"}))
