    DataCaptureConfig.add_member(:initial_sampling_percentage, Smithy::Schema::Shapes::ShapeRef.new(shape: SamplingPercentage, location_name: 'InitialSamplingPercentage', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The percentage of requests SageMaker AI will capture. A lower value is recommended for Endpoints with high traffic.</p>", "smithy.api#required" => {}}))
    DataCaptureConfig.add_member(:destination_s3_uri, Smithy::Schema::Shapes::ShapeRef.new(shape: DestinationS3Uri, location_name: 'DestinationS3Uri', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The Amazon S3 location used to capture the data.</p>", "smithy.api#required" => {}}))
    DataCaptureConfig.add_member(:kms_key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: KmsKeyId, location_name: 'KmsKeyId', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of an Key Management Service key that SageMaker AI uses to encrypt the captured data at rest using Amazon S3 server-side encryption.</p> <p>The KmsKeyId can be any of the following formats: </p> <ul> <li> <p>Key ID: <code>1234abcd-12ab-34cd-56ef-1234567890ab</code> </p> </li> <li> <p>Key ARN: <code>arn:aws:kms:us-west-2:111122223333:key/1234abcd-12ab-34cd-56ef-1234567890ab</code> </p> </li> <li> <p>Alias name: <code>alias/ExampleAlias</code> </p> </li> <li> <p>Alias name ARN: <code>arn:aws:kms:us-west-2:111122223333:alias/ExampleAlias</code> </p> </li> </ul>"}))
    DataCaptureConfig.add_member(:capture_options, Smithy::Schema::Shapes::ShapeRef.new(shape: CaptureOptionList, location_name: 'CaptureOptions', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>Specifies data Model Monitor will capture. You can configure whether to collect only input, only output, or both</p>", "smithy.api#required" => {}}))
