    DescribeTrainingJobResponse.add_member(:model_artifacts, Smithy::Schema::Shapes::ShapeRef.new(shape: ModelArtifacts, location_name: 'ModelArtifacts', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>Information about the Amazon S3 location that is configured for storing model artifacts. </p>", "smithy.api#required" => {}}))
    DescribeTrainingJobResponse.add_member(:training_job_status, Smithy::Schema::Shapes::ShapeRef.new(shape: TrainingJobStatus, location_name: 'TrainingJobStatus', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The status of the training job.</p> <p>SageMaker provides the following training job statuses:</p> <ul> <li> <p> <code>InProgress</code> - The training is in progress.</p> </li> <li> <p> <code>Completed</code> - The training job has completed.</p> </li> <li> <p> <code>Failed</code> - The training job has failed. To see the reason for the failure, see the <code>FailureReason</code> field in the response to a <code>DescribeTrainingJobResponse</code> call.</p> </li> <li> <p> <code>Stopping</code> - The training job is stopping.</p> </li> <li> <p> <code>Stopped</code> - The training job has stopped.</p> </li> </ul> <p>For more detailed information, see <code>SecondaryStatus</code>. </p>", "smithy.api#required" => {}}))
    DescribeTrainingJobResponse.add_member(:secondary_status, Smithy::Schema::Shapes::ShapeRef.new(shape: SecondaryStatus, location_name: 'SecondaryStatus', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p> Provides detailed information about the state of the training job. For detailed information on the secondary status of the training job, see <code>StatusMessage</code> under <a href=\"https://docs.aws.amazon.com/sagemaker/latest/APIReference/API_SecondaryStatusTransition.html\">SecondaryStatusTransition</a>.</p> <p>SageMaker provides primary statuses and secondary statuses that apply to each of them:</p> <dl> <dt>InProgress</dt> <dd> <ul> <li> <p> <code>Starting</code> - Starting the training job.</p> </li> <li> <p> <code>Downloading</code> - An optional stage for algorithms that support <code>File</code> training input mode. It indicates that data is being downloaded to the ML storage volumes.</p> </li> <li> <p> <code>Training</code> - Training is in progress.</p> </li> <li> <p> <code>Interrupted</code> - The job stopped because the managed spot training instances were interrupted. </p> </li> <li> <p> <code>Uploading</code> - Training is complete and the model artifacts are being uploaded to the S3 location.</p> </li> </ul> </dd> <dt>Completed</dt> <dd> <ul> <li> <p> <code>Completed</code> - The training job has completed.</p> </li> </ul> </dd> <dt>Failed</dt> <dd> <ul> <li> <p> <code>Failed</code> - The training job has failed. The reason for the failure is returned in the <code>FailureReason</code> field of <code>DescribeTrainingJobResponse</code>.</p> </li> </ul> </dd> <dt>Stopped</dt> <dd> <ul> <li> <p> <code>MaxRuntimeExceeded</code> - The job stopped because it exceeded the maximum allowed runtime.</p> </li> <li> <p> <code>MaxWaitTimeExceeded</code> - The job stopped because it exceeded the maximum allowed wait time.</p> </li> <li> <p> <code>Stopped</code> - The training job has stopped.</p> </li> </ul> </dd> <dt>Stopping</dt> <dd> <ul> <li> <p> <code>Stopping</code> - Stopping the training job.</p> </li> </ul> </dd> </dl> <important> <p>Valid values for <code>SecondaryStatus</code> are subject to change. </p> </important> <p>We no longer support the following secondary statuses:</p> <ul> <li> <p> <code>LaunchingMLInstances</code> </p> </li> <li> <p> <code>PreparingTraining</code> </p> </li> <li> <p> <code>DownloadingTrainingImage</code> </p> </li> </ul>", "smithy.api#required" => {}}))
    DescribeTrainingJobResponse.add_member(:failure_reason, Smithy::Schema::Shapes::ShapeRef.new(shape: FailureReason, location_name: 'FailureReason', traits: {"smithy.api#documentation" => "<p>If the training job failed, the reason it failed. </p>"}))
    DescribeTrainingJobResponse.add_member(:hyper_parameters, Smithy::Schema::Shapes::ShapeRef.new(shape: HyperParameters, location_name: 'HyperParameters', traits: {"smithy.api#documentation" => "<p>Algorithm-specific parameters. </p>"}))
    DescribeTrainingJobResponse.add_member(:algorithm_specification, Smithy::Schema::Shapes::ShapeRef.new(shape: AlgorithmSpecification, location_name: 'AlgorithmSpecification', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>Information about the algorithm used for training, and algorithm metadata. </p>", "smithy.api#required" => {}}))
    DescribeTrainingJobResponse.add_member(:role_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: RoleArn, location_name: 'RoleArn', traits: {"smithy.api#documentation" => "<p>The Amazon Web Services Identity and Access Management (IAM) role configured for the training job. </p>"}))
    DescribeTrainingJobResponse.add_member(:input_data_config, Smithy::Schema::Shapes::ShapeRef.new(shape: InputDataConfig, location_name: 'InputDataConfig', traits: {"smithy.api#documentation" => "<p>An array of <code>Channel</code> objects that describes each data input channel. </p>"}))
    DescribeTrainingJobResponse.add_member(:output_data_config, Smithy::Schema::Shapes::ShapeRef.new(shape: OutputDataConfig, location_name: 'OutputDataConfig', traits: {"smithy.api#documentation" => "<p>The S3 path where model artifacts that you configured when creating the job are stored. SageMaker creates subfolders for model artifacts. </p>"}))
    DescribeTrainingJobResponse.add_member(:resource_config, Smithy::Schema::Shapes::ShapeRef.new(shape: ResourceConfig, location_name: 'ResourceConfig', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>Resources, including ML compute instances and ML storage volumes, that are configured for model training. </p>", "smithy.api#required" => {}}))
    DescribeTrainingJobResponse.add_member(:warm_pool_status, Smithy::Schema::Shapes::ShapeRef.new(shape: WarmPoolStatus, location_name: 'WarmPoolStatus', traits: {"smithy.api#documentation" => "<p>The status of the warm pool associated with the training job.</p>"}))
    DescribeTrainingJobResponse.add_member(:vpc_config, Smithy::Schema::Shapes::ShapeRef.new(shape: VpcConfig, location_name: 'VpcConfig', traits: {"smithy.api#documentation" => "<p>A <a href=\"https://docs.aws.amazon.com/sagemaker/latest/APIReference/API_VpcConfig.html\">VpcConfig</a> object that specifies the VPC that this training job has access to. For more information, see <a href=\"https://docs.aws.amazon.com/sagemaker/latest/dg/train-vpc.html\">Protect Training Jobs by Using an Amazon Virtual Private Cloud</a>.</p>"}))
    DescribeTrainingJobResponse.add_member(:stopping_condition, Smithy::Schema::Shapes::ShapeRef.new(shape: StoppingCondition, location_name: 'StoppingCondition', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>Specifies a limit to how long a model training job can run. It also specifies how long a managed Spot training job has to complete. When the job reaches the time limit, SageMaker ends the training job. Use this API to cap model training costs.</p> <p>To stop a job, SageMaker sends the algorithm the <code>SIGTERM</code> signal, which delays job termination for 120 seconds. Algorithms can use this 120-second window to save the model artifacts, so the results of training are not lost. </p>", "smithy.api#required" => {}}))
    DescribeTrainingJobResponse.add_member(:creation_time, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'CreationTime', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>A timestamp that indicates when the training job was created.</p>", "smithy.api#required" => {}}))
    DescribeTrainingJobResponse.add_member(:training_start_time, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'TrainingStartTime', traits: {"smithy.api#documentation" => "<p>Indicates the time when the training job starts on training instances. You are billed for the time interval between this time and the value of <code>TrainingEndTime</code>. The start time in CloudWatch Logs might be later than this time. The difference is due to the time it takes to download the training data and to the size of the training container.</p>"}))
    DescribeTrainingJobResponse.add_member(:training_end_time, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'TrainingEndTime', traits: {"smithy.api#documentation" => "<p>Indicates the time when the training job ends on training instances. You are billed for the time interval between the value of <code>TrainingStartTime</code> and this time. For successful jobs and stopped jobs, this is the time after model artifacts are uploaded. For failed jobs, this is the time when SageMaker detects a job failure.</p>"}))
    DescribeTrainingJobResponse.add_member(:last_modified_time, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'LastModifiedTime', traits: {"smithy.api#documentation" => "<p>A timestamp that indicates when the status of the training job was last modified.</p>"}))
    DescribeTrainingJobResponse.add_member(:secondary_status_transitions, Smithy::Schema::Shapes::ShapeRef.new(shape: SecondaryStatusTransitions, location_name: 'SecondaryStatusTransitions', traits: {"smithy.api#documentation" => "<p>A history of all of the secondary statuses that the training job has transitioned through.</p>"}))
    DescribeTrainingJobResponse.add_member(:final_metric_data_list, Smithy::Schema::Shapes::ShapeRef.new(shape: FinalMetricDataList, location_name: 'FinalMetricDataList', traits: {"smithy.api#documentation" => "<p>A collection of <code>MetricData</code> objects that specify the names, values, and dates and times that the training algorithm emitted to Amazon CloudWatch.</p>"}))
    DescribeTrainingJobResponse.add_member(:enable_network_isolation, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'EnableNetworkIsolation', traits: {"smithy.api#documentation" => "<p>If you want to allow inbound or outbound network calls, except for calls between peers within a training cluster for distributed training, choose <code>True</code>. If you enable network isolation for training jobs that are configured to use a VPC, SageMaker downloads and uploads customer data and model artifacts through the specified VPC, but the training container does not have network access.</p>"}))
    DescribeTrainingJobResponse.add_member(:enable_inter_container_traffic_encryption, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'EnableInterContainerTrafficEncryption', traits: {"smithy.api#documentation" => "<p>To encrypt all communications between ML compute instances in distributed training, choose <code>True</code>. Encryption provides greater security for distributed training, but training might take longer. How long it takes depends on the amount of communication between compute instances, especially if you use a deep learning algorithms in distributed training.</p>"}))
    DescribeTrainingJobResponse.add_member(:enable_managed_spot_training, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'EnableManagedSpotTraining', traits: {"smithy.api#documentation" => "<p>A Boolean indicating whether managed spot training is enabled (<code>True</code>) or not (<code>False</code>).</p>"}))
    DescribeTrainingJobResponse.add_member(:checkpoint_config, Smithy::Schema::Shapes::ShapeRef.new(shape: CheckpointConfig, location_name: 'CheckpointConfig'))
    DescribeTrainingJobResponse.add_member(:training_time_in_seconds, Smithy::Schema::Shapes::ShapeRef.new(shape: TrainingTimeInSeconds, location_name: 'TrainingTimeInSeconds', traits: {"smithy.api#documentation" => "<p>The training time in seconds.</p>"}))
    DescribeTrainingJobResponse.add_member(:billable_time_in_seconds, Smithy::Schema::Shapes::ShapeRef.new(shape: BillableTimeInSeconds, location_name: 'BillableTimeInSeconds', traits: {"smithy.api#documentation" => "<p>The billable time in seconds. Billable time refers to the absolute wall-clock time.</p> <p>Multiply <code>BillableTimeInSeconds</code> by the number of instances (<code>InstanceCount</code>) in your training cluster to get the total compute time SageMaker bills you if you run distributed training. The formula is as follows: <code>BillableTimeInSeconds * InstanceCount</code> .</p> <p>You can calculate the savings from using managed spot training using the formula <code>(1 - BillableTimeInSeconds / TrainingTimeInSeconds) * 100</code>. For example, if <code>BillableTimeInSeconds</code> is 100 and <code>TrainingTimeInSeconds</code> is 500, the savings is 80%.</p>"}))
    DescribeTrainingJobResponse.add_member(:debug_hook_config, Smithy::Schema::Shapes::ShapeRef.new(shape: DebugHookConfig, location_name: 'DebugHookConfig'))
    DescribeTrainingJobResponse.add_member(:experiment_config, Smithy::Schema::Shapes::ShapeRef.new(shape: ExperimentConfig, location_name: 'ExperimentConfig'))
    DescribeTrainingJobResponse.add_member(:debug_rule_configurations, Smithy::Schema::Shapes::ShapeRef.new(shape: DebugRuleConfigurations, location_name: 'DebugRuleConfigurations', traits: {"smithy.api#documentation" => "<p>Configuration information for Amazon SageMaker Debugger rules for debugging output tensors.</p>"}))
    DescribeTrainingJobResponse.add_member(:tensor_board_output_config, Smithy::Schema::Shapes::ShapeRef.new(shape: TensorBoardOutputConfig, location_name: 'TensorBoardOutputConfig'))
    DescribeTrainingJobResponse.add_member(:debug_rule_evaluation_statuses, Smithy::Schema::Shapes::ShapeRef.new(shape: DebugRuleEvaluationStatuses, location_name: 'DebugRuleEvaluationStatuses', traits: {"smithy.api#documentation" => "<p>Evaluation status of Amazon SageMaker Debugger rules for debugging on a training job.</p>"}))
    DescribeTrainingJobResponse.add_member(:profiler_config, Smithy::Schema::Shapes::ShapeRef.new(shape: ProfilerConfig, location_name: 'ProfilerConfig'))
    DescribeTrainingJobResponse.add_member(:profiler_rule_configurations, Smithy::Schema::Shapes::ShapeRef.new(shape: ProfilerRuleConfigurations, location_name: 'ProfilerRuleConfigurations', traits: {"smithy.api#documentation" => "<p>Configuration information for Amazon SageMaker Debugger rules for profiling system and framework metrics.</p>"}))
    DescribeTrainingJobResponse.add_member(:profiler_rule_evaluation_statuses, Smithy::Schema::Shapes::ShapeRef.new(shape: ProfilerRuleEvaluationStatuses, location_name: 'ProfilerRuleEvaluationStatuses', traits: {"smithy.api#documentation" => "<p>Evaluation status of Amazon SageMaker Debugger rules for profiling on a training job.</p>"}))
    DescribeTrainingJobResponse.add_member(:profiling_status, Smithy::Schema::Shapes::ShapeRef.new(shape: ProfilingStatus, location_name: 'ProfilingStatus', traits: {"smithy.api#documentation" => "<p>Profiling status of a training job.</p>"}))
    DescribeTrainingJobResponse.add_member(:environment, Smithy::Schema::Shapes::ShapeRef.new(shape: TrainingEnvironmentMap, location_name: 'Environment', traits: {"smithy.api#documentation" => "<p>The environment variables to set in the Docker container.</p> <important> <p>Do not include any security-sensitive information including account access IDs, secrets, or tokens in any environment fields. As part of the shared responsibility model, you are responsible for any potential exposure, unauthorized access, or compromise of your sensitive data if caused by security-sensitive information included in the request environment variable or plain text fields.</p> </important>"}))
    DescribeTrainingJobResponse.add_member(:retry_strategy, Smithy::Schema::Shapes::ShapeRef.new(shape: RetryStrategy, location_name: 'RetryStrategy', traits: {"smithy.api#documentation" => "<p>The number of times to retry the job when the job fails due to an <code>InternalServerError</code>.</p>"}))
    DescribeTrainingJobResponse.add_member(:remote_debug_config, Smithy::Schema::Shapes::ShapeRef.new(shape: RemoteDebugConfig, location_name: 'RemoteDebugConfig', traits: {"smithy.api#documentation" => "<p>Configuration for remote debugging. To learn more about the remote debugging functionality of SageMaker, see <a href=\"https://docs.aws.amazon.com/sagemaker/latest/dg/train-remote-debugging.html\">Access a training container through Amazon Web Services Systems Manager (SSM) for remote debugging</a>.</p>"}))
    DescribeTrainingJobResponse.add_member(:infra_check_config, Smithy::Schema::Shapes::ShapeRef.new(shape: InfraCheckConfig, location_name: 'InfraCheckConfig', traits: {"smithy.api#documentation" => "<p>Contains information about the infrastructure health check configuration for the training job.</p>"}))
