    DescribeTrainingPlanResponse.add_member(:training_plan_name, Smithy::Schema::Shapes::ShapeRef.new(shape: TrainingPlanName, location_name: 'TrainingPlanName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name of the training plan.</p>", "smithy.api#required" => {}}))
    DescribeTrainingPlanResponse.add_member(:status, Smithy::Schema::Shapes::ShapeRef.new(shape: TrainingPlanStatus, location_name: 'Status', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The current status of the training plan (e.g., Pending, Active, Expired). To see the complete list of status values available for a training plan, refer to the <code>Status</code> attribute within the <code> <a href=\"https://docs.aws.amazon.com/sagemaker/latest/APIReference/API_TrainingPlanSummary.html\">TrainingPlanSummary</a> </code> object.</p>", "smithy.api#required" => {}}))
    DescribeTrainingPlanResponse.add_member(:status_message, Smithy::Schema::Shapes::ShapeRef.new(shape: TrainingPlanStatusMessage, location_name: 'StatusMessage', traits: {"smithy.api#documentation" => "<p>A message providing additional information about the current status of the training plan.</p>"}))
    DescribeTrainingPlanResponse.add_member(:duration_hours, Smithy::Schema::Shapes::ShapeRef.new(shape: TrainingPlanDurationHours, location_name: 'DurationHours', traits: {"smithy.api#documentation" => "<p>The number of whole hours in the total duration for this training plan.</p>"}))
    DescribeTrainingPlanResponse.add_member(:duration_minutes, Smithy::Schema::Shapes::ShapeRef.new(shape: TrainingPlanDurationMinutes, location_name: 'DurationMinutes', traits: {"smithy.api#documentation" => "<p>The additional minutes beyond whole hours in the total duration for this training plan.</p>"}))
    DescribeTrainingPlanResponse.add_member(:start_time, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'StartTime', traits: {"smithy.api#documentation" => "<p>The start time of the training plan.</p>"}))
    DescribeTrainingPlanResponse.add_member(:end_time, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'EndTime', traits: {"smithy.api#documentation" => "<p>The end time of the training plan.</p>"}))
    DescribeTrainingPlanResponse.add_member(:upfront_fee, Smithy::Schema::Shapes::ShapeRef.new(shape: String256, location_name: 'UpfrontFee', traits: {"smithy.api#documentation" => "<p>The upfront fee for the training plan.</p>"}))
    DescribeTrainingPlanResponse.add_member(:currency_code, Smithy::Schema::Shapes::ShapeRef.new(shape: CurrencyCode, location_name: 'CurrencyCode', traits: {"smithy.api#documentation" => "<p>The currency code for the upfront fee (e.g., USD).</p>"}))
    DescribeTrainingPlanResponse.add_member(:total_instance_count, Smithy::Schema::Shapes::ShapeRef.new(shape: TotalInstanceCount, location_name: 'TotalInstanceCount', traits: {"smithy.api#documentation" => "<p>The total number of instances reserved in this training plan.</p>"}))
    DescribeTrainingPlanResponse.add_member(:available_instance_count, Smithy::Schema::Shapes::ShapeRef.new(shape: AvailableInstanceCount, location_name: 'AvailableInstanceCount', traits: {"smithy.api#documentation" => "<p>The number of instances currently available for use in this training plan.</p>"}))
    DescribeTrainingPlanResponse.add_member(:in_use_instance_count, Smithy::Schema::Shapes::ShapeRef.new(shape: InUseInstanceCount, location_name: 'InUseInstanceCount', traits: {"smithy.api#documentation" => "<p>The number of instances currently in use from this training plan.</p>"}))
    DescribeTrainingPlanResponse.add_member(:unhealthy_instance_count, Smithy::Schema::Shapes::ShapeRef.new(shape: UnhealthyInstanceCount, location_name: 'UnhealthyInstanceCount', traits: {"smithy.api#documentation" => "<p>The number of instances in the training plan that are currently in an unhealthy state.</p>"}))
    DescribeTrainingPlanResponse.add_member(:available_spare_instance_count, Smithy::Schema::Shapes::ShapeRef.new(shape: AvailableSpareInstanceCount, location_name: 'AvailableSpareInstanceCount', traits: {"smithy.api#documentation" => "<p>The number of available spare instances in the training plan.</p>"}))
    DescribeTrainingPlanResponse.add_member(:total_ultra_server_count, Smithy::Schema::Shapes::ShapeRef.new(shape: UltraServerCount, location_name: 'TotalUltraServerCount', traits: {"smithy.api#documentation" => "<p>The total number of UltraServers reserved to this training plan.</p>"}))
    DescribeTrainingPlanResponse.add_member(:target_resources, Smithy::Schema::Shapes::ShapeRef.new(shape: SageMakerResourceNames, location_name: 'TargetResources', traits: {"smithy.api#documentation" => "<p>The target resources (e.g., SageMaker Training Jobs, SageMaker HyperPod) that can use this training plan.</p> <p>Training plans are specific to their target resource.</p> <ul> <li> <p>A training plan designed for SageMaker training jobs can only be used to schedule and run training jobs.</p> </li> <li> <p>A training plan for HyperPod clusters can be used exclusively to provide compute resources to a cluster's instance group.</p> </li> </ul>"}))
    DescribeTrainingPlanResponse.add_member(:reserved_capacity_summaries, Smithy::Schema::Shapes::ShapeRef.new(shape: ReservedCapacitySummaries, location_name: 'ReservedCapacitySummaries', traits: {"smithy.api#documentation" => "<p>The list of Reserved Capacity providing the underlying compute resources of the plan. </p>"}))
