    DescribeTransformJobRequest.type = Types::DescribeTransformJobRequest
    DescribeTransformJobResponse.add_member(:transform_job_name, Smithy::Schema::Shapes::ShapeRef.new(shape: TransformJobName, location_name: 'TransformJobName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name of the transform job.</p>", "smithy.api#required" => {}}))
    DescribeTransformJobResponse.add_member(:transform_job_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: TransformJobArn, location_name: 'TransformJobArn', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the transform job.</p>", "smithy.api#required" => {}}))
    DescribeTransformJobResponse.add_member(:transform_job_status, Smithy::Schema::Shapes::ShapeRef.new(shape: TransformJobStatus, location_name: 'TransformJobStatus', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The status of the transform job. If the transform job failed, the reason is returned in the <code>FailureReason</code> field.</p>", "smithy.api#required" => {}}))
    DescribeTransformJobResponse.add_member(:failure_reason, Smithy::Schema::Shapes::ShapeRef.new(shape: FailureReason, location_name: 'FailureReason', traits: {"smithy.api#documentation" => "<p>If the transform job failed, <code>FailureReason</code> describes why it failed. A transform job creates a log file, which includes error messages, and stores it as an Amazon S3 object. For more information, see <a href=\"https://docs.aws.amazon.com/sagemaker/latest/dg/logging-cloudwatch.html\">Log Amazon SageMaker Events with Amazon CloudWatch</a>.</p>"}))
    DescribeTransformJobResponse.add_member(:model_name, Smithy::Schema::Shapes::ShapeRef.new(shape: ModelName, location_name: 'ModelName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name of the model used in the transform job.</p>", "smithy.api#required" => {}}))
    DescribeTransformJobResponse.add_member(:max_concurrent_transforms, Smithy::Schema::Shapes::ShapeRef.new(shape: MaxConcurrentTransforms, location_name: 'MaxConcurrentTransforms', traits: {"smithy.api#documentation" => "<p>The maximum number of parallel requests on each instance node that can be launched in a transform job. The default value is 1.</p>"}))
    DescribeTransformJobResponse.add_member(:model_client_config, Smithy::Schema::Shapes::ShapeRef.new(shape: ModelClientConfig, location_name: 'ModelClientConfig', traits: {"smithy.api#documentation" => "<p>The timeout and maximum number of retries for processing a transform job invocation.</p>"}))
    DescribeTransformJobResponse.add_member(:max_payload_in_mb, Smithy::Schema::Shapes::ShapeRef.new(shape: MaxPayloadInMB, location_name: 'MaxPayloadInMB', traits: {"smithy.api#documentation" => "<p>The maximum payload size, in MB, used in the transform job.</p>"}))
    DescribeTransformJobResponse.add_member(:batch_strategy, Smithy::Schema::Shapes::ShapeRef.new(shape: BatchStrategy, location_name: 'BatchStrategy', traits: {"smithy.api#documentation" => "<p>Specifies the number of records to include in a mini-batch for an HTTP inference request. A <i>record</i> <i/> is a single unit of input data that inference can be made on. For example, a single line in a CSV file is a record. </p> <p>To enable the batch strategy, you must set <code>SplitType</code> to <code>Line</code>, <code>RecordIO</code>, or <code>TFRecord</code>.</p>"}))
    DescribeTransformJobResponse.add_member(:environment, Smithy::Schema::Shapes::ShapeRef.new(shape: TransformEnvironmentMap, location_name: 'Environment', traits: {"smithy.api#documentation" => "<p>The environment variables to set in the Docker container. We support up to 16 key and values entries in the map.</p>"}))
    DescribeTransformJobResponse.add_member(:transform_input, Smithy::Schema::Shapes::ShapeRef.new(shape: TransformInput, location_name: 'TransformInput', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>Describes the dataset to be transformed and the Amazon S3 location where it is stored.</p>", "smithy.api#required" => {}}))
    DescribeTransformJobResponse.add_member(:transform_output, Smithy::Schema::Shapes::ShapeRef.new(shape: TransformOutput, location_name: 'TransformOutput', traits: {"smithy.api#documentation" => "<p>Identifies the Amazon S3 location where you want Amazon SageMaker to save the results from the transform job.</p>"}))
    DescribeTransformJobResponse.add_member(:data_capture_config, Smithy::Schema::Shapes::ShapeRef.new(shape: BatchDataCaptureConfig, location_name: 'DataCaptureConfig', traits: {"smithy.api#documentation" => "<p>Configuration to control how SageMaker captures inference data.</p>"}))
