    HumanLoopActivationConfig.add_member(:human_loop_activation_conditions_config, Smithy::Schema::Shapes::ShapeRef.new(shape: HumanLoopActivationConditionsConfig, location_name: 'HumanLoopActivationConditionsConfig', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>Container structure for defining under what conditions SageMaker creates a human loop.</p>", "smithy.api#required" => {}}))
    HumanLoopActivationConfig.type = Types::HumanLoopActivationConfig
    HumanLoopConfig.add_member(:workteam_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: WorkteamArn, location_name: 'WorkteamArn', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>Amazon Resource Name (ARN) of a team of workers. To learn more about the types of workforces and work teams you can create and use with Amazon A2I, see <a href=\"https://docs.aws.amazon.com/sagemaker/latest/dg/sms-workforce-management.html\">Create and Manage Workforces</a>.</p>", "smithy.api#required" => {}}))
    HumanLoopConfig.add_member(:human_task_ui_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: HumanTaskUiArn, location_name: 'HumanTaskUiArn', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the human task user interface.</p> <p>You can use standard HTML and Crowd HTML Elements to create a custom worker task template. You use this template to create a human task UI.</p> <p>To learn how to create a custom HTML template, see <a href=\"https://docs.aws.amazon.com/sagemaker/latest/dg/a2i-custom-templates.html\">Create Custom Worker Task Template</a>.</p> <p>To learn how to create a human task UI, which is a worker task template that can be used in a flow definition, see <a href=\"https://docs.aws.amazon.com/sagemaker/latest/dg/a2i-worker-template-console.html\">Create and Delete a Worker Task Templates</a>.</p>", "smithy.api#required" => {}}))
    HumanLoopConfig.add_member(:task_title, Smithy::Schema::Shapes::ShapeRef.new(shape: FlowDefinitionTaskTitle, location_name: 'TaskTitle', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>A title for the human worker task.</p>", "smithy.api#required" => {}}))
    HumanLoopConfig.add_member(:task_description, Smithy::Schema::Shapes::ShapeRef.new(shape: FlowDefinitionTaskDescription, location_name: 'TaskDescription', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>A description for the human worker task.</p>", "smithy.api#required" => {}}))
    HumanLoopConfig.add_member(:task_count, Smithy::Schema::Shapes::ShapeRef.new(shape: FlowDefinitionTaskCount, location_name: 'TaskCount', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The number of distinct workers who will perform the same task on each object. For example, if <code>TaskCount</code> is set to <code>3</code> for an image classification labeling job, three workers will classify each input image. Increasing <code>TaskCount</code> can improve label accuracy.</p>", "smithy.api#required" => {}}))
    HumanLoopConfig.add_member(:task_availability_lifetime_in_seconds, Smithy::Schema::Shapes::ShapeRef.new(shape: FlowDefinitionTaskAvailabilityLifetimeInSeconds, location_name: 'TaskAvailabilityLifetimeInSeconds', traits: {"smithy.api#documentation" => "<p>The length of time that a task remains available for review by human workers.</p>"}))
    HumanLoopConfig.add_member(:task_time_limit_in_seconds, Smithy::Schema::Shapes::ShapeRef.new(shape: FlowDefinitionTaskTimeLimitInSeconds, location_name: 'TaskTimeLimitInSeconds', traits: {"smithy.api#documentation" => "<p>The amount of time that a worker has to complete a task. The default value is 3,600 seconds (1 hour).</p>"}))
    HumanLoopConfig.add_member(:task_keywords, Smithy::Schema::Shapes::ShapeRef.new(shape: FlowDefinitionTaskKeywords, location_name: 'TaskKeywords', traits: {"smithy.api#documentation" => "<p>Keywords used to describe the task so that workers can discover the task.</p>"}))
