    HumanTaskConfig.add_member(:task_keywords, Smithy::Schema::Shapes::ShapeRef.new(shape: TaskKeywords, location_name: 'TaskKeywords', traits: {"smithy.api#documentation" => "<p>Keywords used to describe the task so that workers on Amazon Mechanical Turk can discover the task.</p>"}))
    HumanTaskConfig.add_member(:task_title, Smithy::Schema::Shapes::ShapeRef.new(shape: TaskTitle, location_name: 'TaskTitle', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>A title for the task for your human workers.</p>", "smithy.api#required" => {}}))
    HumanTaskConfig.add_member(:task_description, Smithy::Schema::Shapes::ShapeRef.new(shape: TaskDescription, location_name: 'TaskDescription', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>A description of the task for your human workers.</p>", "smithy.api#required" => {}}))
    HumanTaskConfig.add_member(:number_of_human_workers_per_data_object, Smithy::Schema::Shapes::ShapeRef.new(shape: NumberOfHumanWorkersPerDataObject, location_name: 'NumberOfHumanWorkersPerDataObject', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The number of human workers that will label an object. </p>", "smithy.api#required" => {}}))
    HumanTaskConfig.add_member(:task_time_limit_in_seconds, Smithy::Schema::Shapes::ShapeRef.new(shape: TaskTimeLimitInSeconds, location_name: 'TaskTimeLimitInSeconds', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The amount of time that a worker has to complete a task. </p> <p>If you create a custom labeling job, the maximum value for this parameter is 8 hours (28,800 seconds).</p> <p>If you create a labeling job using a <a href=\"https://docs.aws.amazon.com/sagemaker/latest/dg/sms-task-types.html\">built-in task type</a> the maximum for this parameter depends on the task type you use:</p> <ul> <li> <p>For <a href=\"https://docs.aws.amazon.com/sagemaker/latest/dg/sms-label-images.html\">image</a> and <a href=\"https://docs.aws.amazon.com/sagemaker/latest/dg/sms-label-text.html\">text</a> labeling jobs, the maximum is 8 hours (28,800 seconds).</p> </li> <li> <p>For <a href=\"https://docs.aws.amazon.com/sagemaker/latest/dg/sms-point-cloud.html\">3D point cloud</a> and <a href=\"https://docs.aws.amazon.com/sagemaker/latest/dg/sms-video.html\">video frame</a> labeling jobs, the maximum is 30 days (2952,000 seconds) for non-AL mode. For most users, the maximum is also 30 days.</p> </li> </ul>", "smithy.api#required" => {}}))
    HumanTaskConfig.add_member(:task_availability_lifetime_in_seconds, Smithy::Schema::Shapes::ShapeRef.new(shape: TaskAvailabilityLifetimeInSeconds, location_name: 'TaskAvailabilityLifetimeInSeconds', traits: {"smithy.api#documentation" => "<p>The length of time that a task remains available for labeling by human workers. The default and maximum values for this parameter depend on the type of workforce you use.</p> <ul> <li> <p>If you choose the Amazon Mechanical Turk workforce, the maximum is 12 hours (43,200 seconds). The default is 6 hours (21,600 seconds).</p> </li> <li> <p>If you choose a private or vendor workforce, the default value is 30 days (2592,000 seconds) for non-AL mode. For most users, the maximum is also 30 days.</p> </li> </ul>"}))
    HumanTaskConfig.add_member(:max_concurrent_task_count, Smithy::Schema::Shapes::ShapeRef.new(shape: MaxConcurrentTaskCount, location_name: 'MaxConcurrentTaskCount', traits: {"smithy.api#documentation" => "<p>Defines the maximum number of data objects that can be labeled by human workers at the same time. Also referred to as batch size. Each object may have more than one worker at one time. The default value is 1000 objects. To increase the maximum value to 5000 objects, contact Amazon Web Services Support.</p>"}))
    HumanTaskConfig.add_member(:annotation_consolidation_config, Smithy::Schema::Shapes::ShapeRef.new(shape: AnnotationConsolidationConfig, location_name: 'AnnotationConsolidationConfig', traits: {"smithy.api#documentation" => "<p>Configures how labels are consolidated across human workers.</p>"}))
    HumanTaskConfig.add_member(:public_workforce_task_price, Smithy::Schema::Shapes::ShapeRef.new(shape: PublicWorkforceTaskPrice, location_name: 'PublicWorkforceTaskPrice', traits: {"smithy.api#documentation" => "<p>The price that you pay for each task performed by an Amazon Mechanical Turk worker.</p>"}))
