    HyperParameterTrainingJobDefinition.add_member(:definition_name, Smithy::Schema::Shapes::ShapeRef.new(shape: HyperParameterTrainingJobDefinitionName, location_name: 'DefinitionName', traits: {"smithy.api#documentation" => "<p>The job definition name.</p>"}))
