    HyperParameterTrainingJobSummary.add_member(:training_job_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: TrainingJobArn, location_name: 'TrainingJobArn', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the training job.</p>", "smithy.api#required" => {}}))
    HyperParameterTrainingJobSummary.add_member(:tuning_job_name, Smithy::Schema::Shapes::ShapeRef.new(shape: HyperParameterTuningJobName, location_name: 'TuningJobName', traits: {"smithy.api#documentation" => "<p>The HyperParameter tuning job that launched the training job.</p>"}))
    HyperParameterTrainingJobSummary.add_member(:creation_time, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'CreationTime', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The date and time that the training job was created.</p>", "smithy.api#required" => {}}))
    HyperParameterTrainingJobSummary.add_member(:training_start_time, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'TrainingStartTime', traits: {"smithy.api#documentation" => "<p>The date and time that the training job started.</p>"}))
    HyperParameterTrainingJobSummary.add_member(:training_end_time, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'TrainingEndTime', traits: {"smithy.api#documentation" => "<p>Specifies the time when the training job ends on training instances. You are billed for the time interval between the value of <code>TrainingStartTime</code> and this time. For successful jobs and stopped jobs, this is the time after model artifacts are uploaded. For failed jobs, this is the time when SageMaker detects a job failure.</p>"}))
    HyperParameterTrainingJobSummary.add_member(:training_job_status, Smithy::Schema::Shapes::ShapeRef.new(shape: TrainingJobStatus, location_name: 'TrainingJobStatus', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The status of the training job.</p>", "smithy.api#required" => {}}))
    HyperParameterTrainingJobSummary.add_member(:tuned_hyper_parameters, Smithy::Schema::Shapes::ShapeRef.new(shape: HyperParameters, location_name: 'TunedHyperParameters', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>A list of the hyperparameters for which you specified ranges to search.</p>", "smithy.api#required" => {}}))
    HyperParameterTrainingJobSummary.add_member(:failure_reason, Smithy::Schema::Shapes::ShapeRef.new(shape: FailureReason, location_name: 'FailureReason', traits: {"smithy.api#documentation" => "<p>The reason that the training job failed. </p>"}))
    HyperParameterTrainingJobSummary.add_member(:final_hyper_parameter_tuning_job_objective_metric, Smithy::Schema::Shapes::ShapeRef.new(shape: FinalHyperParameterTuningJobObjectiveMetric, location_name: 'FinalHyperParameterTuningJobObjectiveMetric', traits: {"smithy.api#documentation" => "<p>The <a href=\"https://docs.aws.amazon.com/sagemaker/latest/APIReference/API_FinalHyperParameterTuningJobObjectiveMetric.html\">FinalHyperParameterTuningJobObjectiveMetric</a> object that specifies the value of the objective metric of the tuning job that launched this training job.</p>"}))
    HyperParameterTrainingJobSummary.add_member(:objective_status, Smithy::Schema::Shapes::ShapeRef.new(shape: ObjectiveStatus, location_name: 'ObjectiveStatus', traits: {"smithy.api#documentation" => "<p>The status of the objective metric for the training job:</p> <ul> <li> <p>Succeeded: The final objective metric for the training job was evaluated by the hyperparameter tuning job and used in the hyperparameter tuning process.</p> </li> </ul> <ul> <li> <p>Pending: The training job is in progress and evaluation of its final objective metric is pending.</p> </li> </ul> <ul> <li> <p>Failed: The final objective metric for the training job was not evaluated, and was not used in the hyperparameter tuning process. This typically occurs when the training job failed or did not emit an objective metric.</p> </li> </ul>"}))
    HyperParameterTrainingJobSummary.type = Types::HyperParameterTrainingJobSummary
    HyperParameterTuningAllocationStrategy.add_member(:prioritized, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'PRIORITIZED', traits: {"smithy.api#enumValue" => "Prioritized"}))
    HyperParameterTuningInstanceConfig.add_member(:instance_type, Smithy::Schema::Shapes::ShapeRef.new(shape: TrainingInstanceType, location_name: 'InstanceType', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The instance type used for processing of hyperparameter optimization jobs. Choose from general purpose (no GPUs) instance types: ml.m5.xlarge, ml.m5.2xlarge, and ml.m5.4xlarge or compute optimized (no GPUs) instance types: ml.c5.xlarge and ml.c5.2xlarge. For more information about instance types, see <a href=\"https://docs.aws.amazon.com/sagemaker/latest/dg/notebooks-available-instance-types.html\">instance type descriptions</a>.</p>", "smithy.api#required" => {}}))
    HyperParameterTuningInstanceConfig.add_member(:instance_count, Smithy::Schema::Shapes::ShapeRef.new(shape: TrainingInstanceCount, location_name: 'InstanceCount', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The number of instances of the type specified by <code>InstanceType</code>. Choose an instance count larger than 1 for distributed training algorithms. See <a href=\"https://docs.aws.amazon.com/sagemaker/latest/dg/data-parallel-use-api.html\">Step 2: Launch a SageMaker Distributed Training Job Using the SageMaker Python SDK</a> for more information.</p>", "smithy.api#required" => {}}))
    HyperParameterTuningInstanceConfig.add_member(:volume_size_in_gb, Smithy::Schema::Shapes::ShapeRef.new(shape: VolumeSizeInGB, location_name: 'VolumeSizeInGB', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The volume size in GB of the data to be processed for hyperparameter optimization (optional).</p>", "smithy.api#required" => {}}))
    HyperParameterTuningInstanceConfig.type = Types::HyperParameterTuningInstanceConfig
    HyperParameterTuningInstanceConfigs.member = Smithy::Schema::Shapes::ShapeRef.new(shape: HyperParameterTuningInstanceConfig)
    HyperParameterTuningJobCompletionDetails.add_member(:number_of_training_jobs_objective_not_improving, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'NumberOfTrainingJobsObjectiveNotImproving', traits: {"smithy.api#documentation" => "<p>The number of training jobs launched by a tuning job that are not improving (1% or less) as measured by model performance evaluated against an objective function.</p>"}))
    HyperParameterTuningJobCompletionDetails.add_member(:convergence_detected_time, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'ConvergenceDetectedTime', traits: {"smithy.api#documentation" => "<p>The time in timestamp format that AMT detected model convergence, as defined by a lack of significant improvement over time based on criteria developed over a wide range of diverse benchmarking tests.</p>"}))
    HyperParameterTuningJobCompletionDetails.type = Types::HyperParameterTuningJobCompletionDetails
    HyperParameterTuningJobConfig.add_member(:strategy, Smithy::Schema::Shapes::ShapeRef.new(shape: HyperParameterTuningJobStrategyType, location_name: 'Strategy', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>Specifies how hyperparameter tuning chooses the combinations of hyperparameter values to use for the training job it launches. For information about search strategies, see <a href=\"https://docs.aws.amazon.com/sagemaker/latest/dg/automatic-model-tuning-how-it-works.html\">How Hyperparameter Tuning Works</a>.</p>", "smithy.api#required" => {}}))
    HyperParameterTuningJobConfig.add_member(:strategy_config, Smithy::Schema::Shapes::ShapeRef.new(shape: HyperParameterTuningJobStrategyConfig, location_name: 'StrategyConfig', traits: {"smithy.api#documentation" => "<p>The configuration for the <code>Hyperband</code> optimization strategy. This parameter should be provided only if <code>Hyperband</code> is selected as the strategy for <code>HyperParameterTuningJobConfig</code>.</p>"}))
    HyperParameterTuningJobConfig.add_member(:hyper_parameter_tuning_job_objective, Smithy::Schema::Shapes::ShapeRef.new(shape: HyperParameterTuningJobObjective, location_name: 'HyperParameterTuningJobObjective', traits: {"smithy.api#documentation" => "<p>The <a href=\"https://docs.aws.amazon.com/sagemaker/latest/APIReference/API_HyperParameterTuningJobObjective.html\">HyperParameterTuningJobObjective</a> specifies the objective metric used to evaluate the performance of training jobs launched by this tuning job.</p>"}))
    HyperParameterTuningJobConfig.add_member(:resource_limits, Smithy::Schema::Shapes::ShapeRef.new(shape: ResourceLimits, location_name: 'ResourceLimits', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The <a href=\"https://docs.aws.amazon.com/sagemaker/latest/APIReference/API_ResourceLimits.html\">ResourceLimits</a> object that specifies the maximum number of training and parallel training jobs that can be used for this hyperparameter tuning job.</p>", "smithy.api#required" => {}}))
    HyperParameterTuningJobConfig.add_member(:parameter_ranges, Smithy::Schema::Shapes::ShapeRef.new(shape: ParameterRanges, location_name: 'ParameterRanges', traits: {"smithy.api#documentation" => "<p>The <a href=\"https://docs.aws.amazon.com/sagemaker/latest/APIReference/API_ParameterRanges.html\">ParameterRanges</a> object that specifies the ranges of hyperparameters that this tuning job searches over to find the optimal configuration for the highest model performance against your chosen objective metric. </p>"}))
    HyperParameterTuningJobConfig.add_member(:training_job_early_stopping_type, Smithy::Schema::Shapes::ShapeRef.new(shape: TrainingJobEarlyStoppingType, location_name: 'TrainingJobEarlyStoppingType', traits: {"smithy.api#documentation" => "<p>Specifies whether to use early stopping for training jobs launched by the hyperparameter tuning job. Because the <code>Hyperband</code> strategy has its own advanced internal early stopping mechanism, <code>TrainingJobEarlyStoppingType</code> must be <code>OFF</code> to use <code>Hyperband</code>. This parameter can take on one of the following values (the default value is <code>OFF</code>):</p> <dl> <dt>OFF</dt> <dd> <p>Training jobs launched by the hyperparameter tuning job do not use early stopping.</p> </dd> <dt>AUTO</dt> <dd> <p>SageMaker stops training jobs launched by the hyperparameter tuning job when they are unlikely to perform better than previously completed training jobs. For more information, see <a href=\"https://docs.aws.amazon.com/sagemaker/latest/dg/automatic-model-tuning-early-stopping.html\">Stop Training Jobs Early</a>.</p> </dd> </dl>"}))
    HyperParameterTuningJobConfig.add_member(:tuning_job_completion_criteria, Smithy::Schema::Shapes::ShapeRef.new(shape: TuningJobCompletionCriteria, location_name: 'TuningJobCompletionCriteria', traits: {"smithy.api#documentation" => "<p>The tuning job's completion criteria.</p>"}))
    HyperParameterTuningJobConfig.add_member(:random_seed, Smithy::Schema::Shapes::ShapeRef.new(shape: RandomSeed, location_name: 'RandomSeed', traits: {"smithy.api#documentation" => "<p>A value used to initialize a pseudo-random number generator. Setting a random seed and using the same seed later for the same tuning job will allow hyperparameter optimization to find more a consistent hyperparameter configuration between the two runs.</p>"}))
    HyperParameterTuningJobConfig.type = Types::HyperParameterTuningJobConfig
    HyperParameterTuningJobConsumedResources.add_member(:runtime_in_seconds, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'RuntimeInSeconds', traits: {"smithy.api#documentation" => "<p>The wall clock runtime in seconds used by your hyperparameter tuning job.</p>"}))
    HyperParameterTuningJobConsumedResources.type = Types::HyperParameterTuningJobConsumedResources
    HyperParameterTuningJobObjective.add_member(:type, Smithy::Schema::Shapes::ShapeRef.new(shape: HyperParameterTuningJobObjectiveType, location_name: 'Type', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>Whether to minimize or maximize the objective metric.</p>", "smithy.api#required" => {}}))
