    IamPolicyConstraints.add_member(:source_ip, Smithy::Schema::Shapes::ShapeRef.new(shape: EnabledOrDisabled, location_name: 'SourceIp', traits: {"smithy.api#documentation" => "<p>When <code>SourceIp</code> is <code>Enabled</code> the worker's IP address when a task is rendered in the worker portal is added to the IAM policy as a <code>Condition</code> used to generate the Amazon S3 presigned URL. This IP address is checked by Amazon S3 and must match in order for the Amazon S3 resource to be rendered in the worker portal.</p>"}))
    IamPolicyConstraints.add_member(:vpc_source_ip, Smithy::Schema::Shapes::ShapeRef.new(shape: EnabledOrDisabled, location_name: 'VpcSourceIp', traits: {"smithy.api#documentation" => "<p>When <code>VpcSourceIp</code> is <code>Enabled</code> the worker's IP address when a task is rendered in private worker portal inside the VPC is added to the IAM policy as a <code>Condition</code> used to generate the Amazon S3 presigned URL. To render the task successfully Amazon S3 checks that the presigned URL is being accessed over an Amazon S3 VPC Endpoint, and that the worker's IP address matches the IP address in the IAM policy. To learn more about configuring private worker portal, see <a href=\"https://docs.aws.amazon.com/sagemaker/latest/dg/samurai-vpc-worker-portal.html\">Use Amazon VPC mode from a private worker portal</a>.</p>"}))
    IamPolicyConstraints.type = Types::IamPolicyConstraints
