    ProcessingS3Input.add_member(:s3_compression_type, Smithy::Schema::Shapes::ShapeRef.new(shape: ProcessingS3CompressionType, location_name: 'S3CompressionType', traits: {"smithy.api#documentation" => "<p>Whether to GZIP-decompress the data in Amazon S3 as it is streamed into the processing container. <code>Gzip</code> can only be used when <code>Pipe</code> mode is specified as the <code>S3InputMode</code>. In <code>Pipe</code> mode, Amazon SageMaker streams input data from the source directly to your container without using the EBS volume.</p>"}))
