    ProductionVariant.add_member(:initial_variant_weight, Smithy::Schema::Shapes::ShapeRef.new(shape: VariantWeight, location_name: 'InitialVariantWeight', traits: {"smithy.api#documentation" => "<p>Determines initial traffic distribution among all of the models that you specify in the endpoint configuration. The traffic to a production variant is determined by the ratio of the <code>VariantWeight</code> to the sum of all <code>VariantWeight</code> values across all ProductionVariants. If unspecified, it defaults to 1.0. </p>"}))
    ProductionVariant.add_member(:accelerator_type, Smithy::Schema::Shapes::ShapeRef.new(shape: ProductionVariantAcceleratorType, location_name: 'AcceleratorType', traits: {"smithy.api#documentation" => "<p>This parameter is no longer supported. Elastic Inference (EI) is no longer available.</p> <p>This parameter was used to specify the size of the EI instance to use for the production variant.</p>"}))
    ProductionVariant.add_member(:core_dump_config, Smithy::Schema::Shapes::ShapeRef.new(shape: ProductionVariantCoreDumpConfig, location_name: 'CoreDumpConfig', traits: {"smithy.api#documentation" => "<p>Specifies configuration for a core dump from the model container when the process crashes.</p>"}))
    ProductionVariant.add_member(:serverless_config, Smithy::Schema::Shapes::ShapeRef.new(shape: ProductionVariantServerlessConfig, location_name: 'ServerlessConfig', traits: {"smithy.api#documentation" => "<p>The serverless configuration for an endpoint. Specifies a serverless endpoint configuration instead of an instance-based endpoint configuration.</p>"}))
    ProductionVariant.add_member(:volume_size_in_gb, Smithy::Schema::Shapes::ShapeRef.new(shape: ProductionVariantVolumeSizeInGB, location_name: 'VolumeSizeInGB', traits: {"smithy.api#documentation" => "<p>The size, in GB, of the ML storage volume attached to individual inference instance associated with the production variant. Currently only Amazon EBS gp2 storage volumes are supported.</p>"}))
    ProductionVariant.add_member(:model_data_download_timeout_in_seconds, Smithy::Schema::Shapes::ShapeRef.new(shape: ProductionVariantModelDataDownloadTimeoutInSeconds, location_name: 'ModelDataDownloadTimeoutInSeconds', traits: {"smithy.api#documentation" => "<p>The timeout value, in seconds, to download and extract the model that you want to host from Amazon S3 to the individual inference instance associated with this production variant.</p>"}))
    ProductionVariant.add_member(:container_startup_health_check_timeout_in_seconds, Smithy::Schema::Shapes::ShapeRef.new(shape: ProductionVariantContainerStartupHealthCheckTimeoutInSeconds, location_name: 'ContainerStartupHealthCheckTimeoutInSeconds', traits: {"smithy.api#documentation" => "<p>The timeout value, in seconds, for your inference container to pass health check by SageMaker Hosting. For more information about health check, see <a href=\"https://docs.aws.amazon.com/sagemaker/latest/dg/your-algorithms-inference-code.html#your-algorithms-inference-algo-ping-requests\">How Your Container Should Respond to Health Check (Ping) Requests</a>.</p>"}))
    ProductionVariant.add_member(:enable_ssm_access, Smithy::Schema::Shapes::ShapeRef.new(shape: ProductionVariantSSMAccess, location_name: 'EnableSSMAccess', traits: {"smithy.api#documentation" => "<p> You can use this parameter to turn on native Amazon Web Services Systems Manager (SSM) access for a production variant behind an endpoint. By default, SSM access is disabled for all production variants behind an endpoint. You can turn on or turn off SSM access for a production variant behind an existing endpoint by creating a new endpoint configuration and calling <code>UpdateEndpoint</code>. </p>"}))
    ProductionVariant.add_member(:managed_instance_scaling, Smithy::Schema::Shapes::ShapeRef.new(shape: ProductionVariantManagedInstanceScaling, location_name: 'ManagedInstanceScaling', traits: {"smithy.api#documentation" => "<p>Settings that control the range in the number of instances that the endpoint provisions as it scales up or down to accommodate traffic. </p>"}))
    ProductionVariant.add_member(:routing_config, Smithy::Schema::Shapes::ShapeRef.new(shape: ProductionVariantRoutingConfig, location_name: 'RoutingConfig', traits: {"smithy.api#documentation" => "<p>Settings that control how the endpoint routes incoming traffic to the instances that the endpoint hosts.</p>"}))
    ProductionVariant.add_member(:inference_ami_version, Smithy::Schema::Shapes::ShapeRef.new(shape: ProductionVariantInferenceAmiVersion, location_name: 'InferenceAmiVersion', traits: {"smithy.api#documentation" => "<p>Specifies an option from a collection of preconfigured Amazon Machine Image (AMI) images. Each image is configured by Amazon Web Services with a set of software and driver versions. Amazon Web Services optimizes these configurations for different machine learning workloads.</p> <p>By selecting an AMI version, you can ensure that your inference environment is compatible with specific software requirements, such as CUDA driver versions, Linux kernel versions, or Amazon Web Services Neuron driver versions.</p> <p>The AMI version names, and their configurations, are the following:</p> <dl> <dt>al2-ami-sagemaker-inference-gpu-2</dt> <dd> <ul> <li> <p>Accelerator: GPU</p> </li> <li> <p>NVIDIA driver version: 535</p> </li> <li> <p>CUDA version: 12.2</p> </li> </ul> </dd> <dt>al2-ami-sagemaker-inference-gpu-2-1</dt> <dd> <ul> <li> <p>Accelerator: GPU</p> </li> <li> <p>NVIDIA driver version: 535</p> </li> <li> <p>CUDA version: 12.2</p> </li> <li> <p>NVIDIA Container Toolkit with disabled CUDA-compat mounting</p> </li> </ul> </dd> <dt>al2-ami-sagemaker-inference-gpu-3-1</dt> <dd> <ul> <li> <p>Accelerator: GPU</p> </li> <li> <p>NVIDIA driver version: 550</p> </li> <li> <p>CUDA version: 12.4</p> </li> <li> <p>NVIDIA Container Toolkit with disabled CUDA-compat mounting</p> </li> </ul> </dd> <dt>al2-ami-sagemaker-inference-neuron-2</dt> <dd> <ul> <li> <p>Accelerator: Inferentia2 and Trainium</p> </li> <li> <p>Neuron driver version: 2.19</p> </li> </ul> </dd> </dl>"}))
    ProductionVariant.add_member(:capacity_reservation_config, Smithy::Schema::Shapes::ShapeRef.new(shape: ProductionVariantCapacityReservationConfig, location_name: 'CapacityReservationConfig', traits: {"smithy.api#documentation" => "<p>Settings for the capacity reservation for the compute instances that SageMaker AI reserves for an endpoint. </p>"}))
