    ProductionVariantCapacityReservationSummary.add_member(:capacity_reservation_preference, Smithy::Schema::Shapes::ShapeRef.new(shape: CapacityReservationPreference, location_name: 'CapacityReservationPreference', traits: {"smithy.api#documentation" => "<p>The option that you chose for the capacity reservation. SageMaker AI supports the following options:</p> <dl> <dt>capacity-reservations-only</dt> <dd> <p>SageMaker AI launches instances only into an ML capacity reservation. If no capacity is available, the instances fail to launch.</p> </dd> </dl>"}))
