    ProductionVariantRoutingConfig.add_member(:routing_strategy, Smithy::Schema::Shapes::ShapeRef.new(shape: RoutingStrategy, location_name: 'RoutingStrategy', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>Sets how the endpoint routes incoming traffic:</p> <ul> <li> <p> <code>LEAST_OUTSTANDING_REQUESTS</code>: The endpoint routes requests to the specific instances that have more capacity to process them.</p> </li> <li> <p> <code>RANDOM</code>: The endpoint routes each request to a randomly chosen instance.</p> </li> </ul>", "smithy.api#required" => {}}))
