    ProductionVariantServerlessConfig.add_member(:max_concurrency, Smithy::Schema::Shapes::ShapeRef.new(shape: ServerlessMaxConcurrency, location_name: 'MaxConcurrency', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The maximum number of concurrent invocations your serverless endpoint can process.</p>", "smithy.api#required" => {}}))
    ProductionVariantServerlessConfig.add_member(:provisioned_concurrency, Smithy::Schema::Shapes::ShapeRef.new(shape: ServerlessProvisionedConcurrency, location_name: 'ProvisionedConcurrency', traits: {"smithy.api#documentation" => "<p>The amount of provisioned concurrency to allocate for the serverless endpoint. Should be less than or equal to <code>MaxConcurrency</code>.</p> <note> <p>This field is not supported for serverless endpoint recommendations for Inference Recommender jobs. For more information about creating an Inference Recommender job, see <a href=\"https://docs.aws.amazon.com/sagemaker/latest/APIReference/API_CreateInferenceRecommendationsJob.html\">CreateInferenceRecommendationsJobs</a>.</p> </note>"}))
