    ProductionVariantServerlessUpdateConfig.add_member(:provisioned_concurrency, Smithy::Schema::Shapes::ShapeRef.new(shape: ServerlessProvisionedConcurrency, location_name: 'ProvisionedConcurrency', traits: {"smithy.api#documentation" => "<p>The updated amount of provisioned concurrency to allocate for the serverless endpoint. Should be less than or equal to <code>MaxConcurrency</code>.</p>"}))
