    S3StorageConfig.add_member(:kms_key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: KmsKeyId, location_name: 'KmsKeyId', traits: {"smithy.api#documentation" => "<p>The Amazon Web Services Key Management Service (KMS) key ARN of the key used to encrypt any objects written into the <code>OfflineStore</code> S3 location.</p> <p>The IAM <code>roleARN</code> that is passed as a parameter to <code>CreateFeatureGroup</code> must have below permissions to the <code>KmsKeyId</code>:</p> <ul> <li> <p> <code>\"kms:GenerateDataKey\"</code> </p> </li> </ul>"}))
    S3StorageConfig.add_member(:resolved_output_s3_uri, Smithy::Schema::Shapes::ShapeRef.new(shape: S3Uri, location_name: 'ResolvedOutputS3Uri', traits: {"smithy.api#documentation" => "<p>The S3 path where offline records are written.</p>"}))
