    ScalingPolicyMetric.add_member(:invocations_per_instance, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'InvocationsPerInstance', traits: {"smithy.api#documentation" => "<p>The number of invocations sent to a model, normalized by <code>InstanceCount</code> in each ProductionVariant. <code>1/numberOfInstances</code> is sent as the value on each request, where <code>numberOfInstances</code> is the number of active instances for the ProductionVariant behind the endpoint at the time of the request.</p>"}))
    ScalingPolicyMetric.add_member(:model_latency, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'ModelLatency', traits: {"smithy.api#documentation" => "<p>The interval of time taken by a model to respond as viewed from SageMaker. This interval includes the local communication times taken to send the request and to fetch the response from the container of a model and the time taken to complete the inference in the container.</p>"}))
