    ScheduledUpdateConfig.add_member(:deployment_config, Smithy::Schema::Shapes::ShapeRef.new(shape: DeploymentConfiguration, location_name: 'DeploymentConfig', traits: {"smithy.api#documentation" => "<p>The configuration to use when updating the AMI versions.</p>"}))
    ScheduledUpdateConfig.type = Types::ScheduledUpdateConfig
    SchedulerConfig.add_member(:priority_classes, Smithy::Schema::Shapes::ShapeRef.new(shape: PriorityClassList, location_name: 'PriorityClasses', traits: {"smithy.api#documentation" => "<p>List of the priority classes, <code>PriorityClass</code>, of the cluster policy. When specified, these class configurations define how tasks are queued.</p>"}))
    SchedulerConfig.add_member(:fair_share, Smithy::Schema::Shapes::ShapeRef.new(shape: FairShare, location_name: 'FairShare', traits: {"smithy.api#documentation" => "<p>When enabled, entities borrow idle compute based on their assigned <code>FairShareWeight</code>.</p> <p>When disabled, entities borrow idle compute based on a first-come first-serve basis.</p> <p>Default is <code>Enabled</code>.</p>"}))
