    TargetPlatform.add_member(:os, Smithy::Schema::Shapes::ShapeRef.new(shape: TargetPlatformOs, location_name: 'Os', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>Specifies a target platform OS.</p> <ul> <li> <p> <code>LINUX</code>: Linux-based operating systems.</p> </li> <li> <p> <code>ANDROID</code>: Android operating systems. Android API level can be specified using the <code>ANDROID_PLATFORM</code> compiler option. For example, <code>\"CompilerOptions\": {'ANDROID_PLATFORM': 28}</code> </p> </li> </ul>", "smithy.api#required" => {}}))
    TargetPlatform.add_member(:arch, Smithy::Schema::Shapes::ShapeRef.new(shape: TargetPlatformArch, location_name: 'Arch', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>Specifies a target platform architecture.</p> <ul> <li> <p> <code>X86_64</code>: 64-bit version of the x86 instruction set.</p> </li> <li> <p> <code>X86</code>: 32-bit version of the x86 instruction set.</p> </li> <li> <p> <code>ARM64</code>: ARMv8 64-bit CPU.</p> </li> <li> <p> <code>ARM_EABIHF</code>: ARMv7 32-bit, Hard Float.</p> </li> <li> <p> <code>ARM_EABI</code>: ARMv7 32-bit, Soft Float. Used by Android 32-bit ARM platform.</p> </li> </ul>", "smithy.api#required" => {}}))
