    TextClassificationJobConfig.add_member(:completion_criteria, Smithy::Schema::Shapes::ShapeRef.new(shape: AutoMLJobCompletionCriteria, location_name: 'CompletionCriteria', traits: {"smithy.api#documentation" => "<p>How long a job is allowed to run, or how many candidates a job is allowed to generate.</p>"}))
    TextClassificationJobConfig.add_member(:content_column, Smithy::Schema::Shapes::ShapeRef.new(shape: ContentColumn, location_name: 'ContentColumn', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name of the column used to provide the sentences to be classified. It should not be the same as the target column.</p>", "smithy.api#required" => {}}))
