    ThroughputConfig.add_member(:provisioned_read_capacity_units, Smithy::Schema::Shapes::ShapeRef.new(shape: CapacityUnit, location_name: 'ProvisionedReadCapacityUnits', traits: {"smithy.api#documentation" => "<p> For provisioned feature groups with online store enabled, this indicates the read throughput you are billed for and can consume without throttling. </p> <p>This field is not applicable for on-demand feature groups. </p>"}))
    ThroughputConfig.add_member(:provisioned_write_capacity_units, Smithy::Schema::Shapes::ShapeRef.new(shape: CapacityUnit, location_name: 'ProvisionedWriteCapacityUnits', traits: {"smithy.api#documentation" => "<p> For provisioned feature groups, this indicates the write throughput you are billed for and can consume without throttling. </p> <p>This field is not applicable for on-demand feature groups. </p>"}))
    ThroughputConfig.type = Types::ThroughputConfig
    ThroughputConfigDescription.add_member(:throughput_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: ThroughputMode, location_name: 'ThroughputMode', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The mode used for your feature group throughput: <code>ON_DEMAND</code> or <code>PROVISIONED</code>. </p>", "smithy.api#required" => {}}))
    ThroughputConfigDescription.add_member(:provisioned_read_capacity_units, Smithy::Schema::Shapes::ShapeRef.new(shape: CapacityUnit, location_name: 'ProvisionedReadCapacityUnits', traits: {"smithy.api#documentation" => "<p> For provisioned feature groups with online store enabled, this indicates the read throughput you are billed for and can consume without throttling. </p> <p>This field is not applicable for on-demand feature groups. </p>"}))
