    ThroughputConfigDescription.type = Types::ThroughputConfigDescription
    ThroughputConfigUpdate.add_member(:throughput_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: ThroughputMode, location_name: 'ThroughputMode', traits: {"smithy.api#documentation" => "<p>Target throughput mode of the feature group. Throughput update is an asynchronous operation, and the outcome should be monitored by polling <code>LastUpdateStatus</code> field in <code>DescribeFeatureGroup</code> response. You cannot update a feature group's throughput while another update is in progress. </p>"}))
    ThroughputConfigUpdate.add_member(:provisioned_read_capacity_units, Smithy::Schema::Shapes::ShapeRef.new(shape: CapacityUnit, location_name: 'ProvisionedReadCapacityUnits', traits: {"smithy.api#documentation" => "<p>For provisioned feature groups with online store enabled, this indicates the read throughput you are billed for and can consume without throttling. </p>"}))
