    TransformJob.add_member(:transform_job_name, Smithy::Schema::Shapes::ShapeRef.new(shape: TransformJobName, location_name: 'TransformJobName', traits: {"smithy.api#documentation" => "<p>The name of the transform job.</p>"}))
    TransformJob.add_member(:transform_job_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: TransformJobArn, location_name: 'TransformJobArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the transform job.</p>"}))
    TransformJob.add_member(:transform_job_status, Smithy::Schema::Shapes::ShapeRef.new(shape: TransformJobStatus, location_name: 'TransformJobStatus', traits: {"smithy.api#documentation" => "<p>The status of the transform job.</p> <p>Transform job statuses are:</p> <ul> <li> <p> <code>InProgress</code> - The job is in progress.</p> </li> <li> <p> <code>Completed</code> - The job has completed.</p> </li> <li> <p> <code>Failed</code> - The transform job has failed. To see the reason for the failure, see the <code>FailureReason</code> field in the response to a <code>DescribeTransformJob</code> call.</p> </li> <li> <p> <code>Stopping</code> - The transform job is stopping.</p> </li> <li> <p> <code>Stopped</code> - The transform job has stopped.</p> </li> </ul>"}))
    TransformJob.add_member(:failure_reason, Smithy::Schema::Shapes::ShapeRef.new(shape: FailureReason, location_name: 'FailureReason', traits: {"smithy.api#documentation" => "<p>If the transform job failed, the reason it failed.</p>"}))
    TransformJob.add_member(:model_name, Smithy::Schema::Shapes::ShapeRef.new(shape: ModelName, location_name: 'ModelName', traits: {"smithy.api#documentation" => "<p>The name of the model associated with the transform job.</p>"}))
    TransformJob.add_member(:max_concurrent_transforms, Smithy::Schema::Shapes::ShapeRef.new(shape: MaxConcurrentTransforms, location_name: 'MaxConcurrentTransforms', traits: {"smithy.api#documentation" => "<p>The maximum number of parallel requests that can be sent to each instance in a transform job. If <code>MaxConcurrentTransforms</code> is set to 0 or left unset, SageMaker checks the optional execution-parameters to determine the settings for your chosen algorithm. If the execution-parameters endpoint is not enabled, the default value is 1. For built-in algorithms, you don't need to set a value for <code>MaxConcurrentTransforms</code>.</p>"}))
    TransformJob.add_member(:model_client_config, Smithy::Schema::Shapes::ShapeRef.new(shape: ModelClientConfig, location_name: 'ModelClientConfig'))
    TransformJob.add_member(:max_payload_in_mb, Smithy::Schema::Shapes::ShapeRef.new(shape: MaxPayloadInMB, location_name: 'MaxPayloadInMB', traits: {"smithy.api#documentation" => "<p>The maximum allowed size of the payload, in MB. A payload is the data portion of a record (without metadata). The value in <code>MaxPayloadInMB</code> must be greater than, or equal to, the size of a single record. To estimate the size of a record in MB, divide the size of your dataset by the number of records. To ensure that the records fit within the maximum payload size, we recommend using a slightly larger value. The default value is 6 MB. For cases where the payload might be arbitrarily large and is transmitted using HTTP chunked encoding, set the value to 0. This feature works only in supported algorithms. Currently, SageMaker built-in algorithms do not support HTTP chunked encoding.</p>"}))
    TransformJob.add_member(:batch_strategy, Smithy::Schema::Shapes::ShapeRef.new(shape: BatchStrategy, location_name: 'BatchStrategy', traits: {"smithy.api#documentation" => "<p>Specifies the number of records to include in a mini-batch for an HTTP inference request. A record is a single unit of input data that inference can be made on. For example, a single line in a CSV file is a record.</p>"}))
    TransformJob.add_member(:environment, Smithy::Schema::Shapes::ShapeRef.new(shape: TransformEnvironmentMap, location_name: 'Environment', traits: {"smithy.api#documentation" => "<p>The environment variables to set in the Docker container. We support up to 16 key and values entries in the map.</p>"}))
    TransformJob.add_member(:transform_input, Smithy::Schema::Shapes::ShapeRef.new(shape: TransformInput, location_name: 'TransformInput'))
    TransformJob.add_member(:transform_output, Smithy::Schema::Shapes::ShapeRef.new(shape: TransformOutput, location_name: 'TransformOutput'))
    TransformJob.add_member(:data_capture_config, Smithy::Schema::Shapes::ShapeRef.new(shape: BatchDataCaptureConfig, location_name: 'DataCaptureConfig'))
    TransformJob.add_member(:transform_resources, Smithy::Schema::Shapes::ShapeRef.new(shape: TransformResources, location_name: 'TransformResources'))
    TransformJob.add_member(:creation_time, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'CreationTime', traits: {"smithy.api#documentation" => "<p>A timestamp that shows when the transform Job was created.</p>"}))
    TransformJob.add_member(:transform_start_time, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'TransformStartTime', traits: {"smithy.api#documentation" => "<p>Indicates when the transform job starts on ML instances. You are billed for the time interval between this time and the value of <code>TransformEndTime</code>.</p>"}))
    TransformJob.add_member(:transform_end_time, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'TransformEndTime', traits: {"smithy.api#documentation" => "<p>Indicates when the transform job has been completed, or has stopped or failed. You are billed for the time interval between this time and the value of <code>TransformStartTime</code>.</p>"}))
    TransformJob.add_member(:labeling_job_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: LabelingJobArn, location_name: 'LabelingJobArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the labeling job that created the transform job.</p>"}))
    TransformJob.add_member(:auto_ml_job_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: AutoMLJobArn, location_name: 'AutoMLJobArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the AutoML job that created the transform job.</p>"}))
