    TransformJobDefinition.add_member(:max_concurrent_transforms, Smithy::Schema::Shapes::ShapeRef.new(shape: MaxConcurrentTransforms, location_name: 'MaxConcurrentTransforms', traits: {"smithy.api#documentation" => "<p>The maximum number of parallel requests that can be sent to each instance in a transform job. The default value is 1.</p>"}))
    TransformJobDefinition.add_member(:max_payload_in_mb, Smithy::Schema::Shapes::ShapeRef.new(shape: MaxPayloadInMB, location_name: 'MaxPayloadInMB', traits: {"smithy.api#documentation" => "<p>The maximum payload size allowed, in MB. A payload is the data portion of a record (without metadata).</p>"}))
    TransformJobDefinition.add_member(:batch_strategy, Smithy::Schema::Shapes::ShapeRef.new(shape: BatchStrategy, location_name: 'BatchStrategy', traits: {"smithy.api#documentation" => "<p>A string that determines the number of records included in a single mini-batch.</p> <p> <code>SingleRecord</code> means only one record is used per mini-batch. <code>MultiRecord</code> means a mini-batch is set to contain as many records that can fit within the <code>MaxPayloadInMB</code> limit.</p>"}))
    TransformJobDefinition.add_member(:environment, Smithy::Schema::Shapes::ShapeRef.new(shape: TransformEnvironmentMap, location_name: 'Environment', traits: {"smithy.api#documentation" => "<p>The environment variables to set in the Docker container. We support up to 16 key and values entries in the map.</p>"}))
    TransformJobDefinition.add_member(:transform_input, Smithy::Schema::Shapes::ShapeRef.new(shape: TransformInput, location_name: 'TransformInput', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>A description of the input source and the way the transform job consumes it.</p>", "smithy.api#required" => {}}))
    TransformJobDefinition.add_member(:transform_output, Smithy::Schema::Shapes::ShapeRef.new(shape: TransformOutput, location_name: 'TransformOutput', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>Identifies the Amazon S3 location where you want Amazon SageMaker to save the results from the transform job.</p>", "smithy.api#required" => {}}))
    TransformJobDefinition.add_member(:transform_resources, Smithy::Schema::Shapes::ShapeRef.new(shape: TransformResources, location_name: 'TransformResources', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>Identifies the ML compute instances for the transform job.</p>", "smithy.api#required" => {}}))
