    TransformJobSummary.add_member(:transform_job_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: TransformJobArn, location_name: 'TransformJobArn', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the transform job.</p>", "smithy.api#required" => {}}))
