    TransformJobSummary.add_member(:transform_end_time, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'TransformEndTime', traits: {"smithy.api#documentation" => "<p>Indicates when the transform job ends on compute instances. For successful jobs and stopped jobs, this is the exact time recorded after the results are uploaded. For failed jobs, this is when Amazon SageMaker detected that the job failed.</p>"}))
    TransformJobSummary.add_member(:last_modified_time, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'LastModifiedTime', traits: {"smithy.api#documentation" => "<p>Indicates when the transform job was last modified.</p>"}))
    TransformJobSummary.add_member(:transform_job_status, Smithy::Schema::Shapes::ShapeRef.new(shape: TransformJobStatus, location_name: 'TransformJobStatus', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The status of the transform job.</p>", "smithy.api#required" => {}}))
