    UserSettings.add_member(:r_session_app_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: RSessionAppSettings, location_name: 'RSessionAppSettings', traits: {"smithy.api#documentation" => "<p>A collection of settings that configure the <code>RSessionGateway</code> app.</p>"}))
